window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch08"]={"id":"ch08","title":"第四章 细胞骨架 · 第三节 中间纤维","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"中间纤维 · 类型 · 装配 · 功能","modules":[{"i":0,"name":"第三节 中间纤维 · 三、中间纤维(intermediate filaments, IFs)","slides":[{"i":0,"sec":"三、中间纤维(intermediate ","title":"三、中间纤维(intermediate filaments, IFs)","notes":"同)，在脊椎动物细胞中多见。\nat least 10 times more abundant than F-actin&MT.\n(tubulin-GTP/GDP; actin-ATP/ADP)\n和非离子去垢剂处理时，只有它能稳定存在，其它大\n部分的细胞骨架都被破坏。\n【结合课本/笔记】·纤毛运动机制三、中间纤维（intermediate filament,IF)10nm纤维,因其直径介于肌粗丝和细丝之间, 故被命名为中间纤维。IF几乎分布于所有动物细胞，往往形成一个网络结构，特别是在需要承受机械压力的细胞中含量相当丰富。如上皮细胞中。除了胞质中，在内核膜下的核纤层也属于IF。●中间纤维的装配●中间纤维的成分与分布●中间纤维结合蛋白（ IFAP ）及其判定标准●中间纤维的功能中间纤维的装配◆中间纤维装配过程◆IF装配与MF,MT装配相比，有以下几个特点：·IF装配的单体是纤维状蛋白(MF,MT的单体呈球形)；·反向平行的四聚体导致IF不具有极性；·IF在体外装配时不需要核苷酸或结合蛋白的辅助，在体内装配后，细胞中几","page":1,"level":"掌握","img":"assets/img/ch08/p001.jpg","anim":null,"fig":null,"points":["直径10nm vs (微丝7nm, 微管 24nm)","不是所有真核细胞所必需的结构组分(与微管微丝不","在表皮细胞及神经轴突(axons of neurons)中, IFs are","其组成蛋白不与核苷酸结合","三种细胞骨架丝中，中间纤维最为坚韧耐久，高盐"],"check":{"q":"关于中间纤维(IFs)的特点，下列叙述正确的是？","o":["A. 具有极性，装配需GTP","B. 直径约10nm，单体为纤维状蛋白，装配不需要核苷酸","C. 所有真核细胞都必需，且与核苷酸结合","D. 直径约7nm，单体为球形蛋白"],"a":"B","e":"中间纤维直径约10nm，单体为纤维状蛋白，反向平行四聚体使其无极性，装配不需核苷酸或结合蛋白辅助，是三种骨架中最坚韧耐久的。","oe":["反向平行四聚体使IF无极性，装配不需GTP。","IF直径约10nm、单体呈纤维状且装配不需核苷酸。","IF不是所有真核细胞必需，也不与核苷酸结合。","直径7nm与球形单体描述的是微丝。"]},"cards":null,"mem":"中间纤维10nm，介于7与24，耐去垢剂最稳定","big":"assets/img/ch08/big/p001.jpg","terms":[{"t":"中间纤维","en":"intermediate filament, IF","d":"直径约10nm、无极性、具组织特异性的细胞骨架纤维。"},{"t":"中间纤维结合蛋白","en":"IFAP","d":"与中间纤维结合、调节其组装、交联或与其它结构连接的蛋白。"}]},{"i":1,"sec":"三、中间纤维(intermediate ","title":"control","notes":"Disrupted this gene\nCrescentin, the domains of\neukaryotic intermediate filaments\n【中文讲解·对照课本/考点】\n考点：第三节 中间纤维 · 三、中间纤维(intermediate filaments, IFs) ｜ 教材：第十章 细胞骨架 · 第三节 中间丝（教材 p221–226）\n• ·纤毛运动机制三、中间纤维（intermediate filament,IF)10nm纤维,因其直径介于肌粗丝和细丝之间, 故被命名为中间纤维。IF几乎分布于所有动物细胞，往往形成一个网络结构，特别是在需要承受机械压力的细胞中含量相当丰富。如上皮细胞中。除了胞质中，在内核膜下的核纤层也属于IF。●中间纤维的装配●中间纤维的成分与分布●中间纤维结合蛋白（ IFAP ）及其判定标准●中间纤维的功能中间纤维的装配◆中间纤维装配过程◆IF装配与MF,MT装配相比，有以下几个特点：·I\n\n【本页英文讲解】\n本页以新月柄杆菌为例，对比展示中间纤维（intermediate filaments, IF）的结构域：设有对照组（control）与敲除该基因（disrupted this gene）两种状态，并指出新月柄杆菌素含真核IF结构域。考点：提示原核细胞已有IF样蛋白，与翟中和《细胞生物学》第十章IF由杆状结构域组成相联系。","page":2,"level":"掌握","img":"assets/img/ch08/p002.jpg","anim":null,"fig":null,"points":["新月柄杆菌素(crescentin)含真核中间纤维的结构域","提示原核细胞已具有IF样蛋白，细胞骨架蛋白在进化上高度保守"],"check":{"q":"新月柄杆菌素（crescentin）的研究提示？","o":["A. 原核细胞不存在任何细胞骨架蛋白","B. 它属于微管蛋白家族成员","C. 原核细胞已具有含真核中间纤维结构域的蛋白","D. 它属于肌动蛋白家族成员"],"a":"C","e":"新月柄杆菌素含真核中间纤维的结构域，提示原核细胞已具有IF样蛋白，说明细胞骨架蛋白在进化上高度保守。","oe":["A. 错误，原核细胞已有骨架样蛋白，此项错误。","B. 错误，crescentin含IF结构域，不是微管蛋白。","C. 正确，提示原核已有含IF结构域的蛋白。","D. 错误，crescentin并非肌动蛋白家族的成员。"]},"cards":null,"mem":"新月蛋白：细菌中中间纤维同源，证其保守","big":"assets/img/ch08/big/p002.jpg","terms":[{"t":"新月柄杆菌素","en":"crescentin","d":"细菌中含真核中间纤维结构域的蛋白，决定细胞的弯曲形态。"}]}],"mcq":[],"judge":[{"id":"ch08_ajudge_2","modI":0,"q":"直径10nm vs (微丝7nm, 微管 24nm)","a":"对","e":"本页要点：直径10nm vs (微丝7nm, 微管 24nm)","kp":"ch08_s0_0","oe":["胶质细胞中含胶质纤维酸性蛋白(GFAP)组成的胶质丝，表述正确。","若判错，则胶质细胞确含胶质丝，否定缺乏依据。"]}],"fill":[],"short":[],"calc":[],"term":[]},{"i":1,"name":"第三节 中间纤维 · 3.1 组成成分","slides":[{"i":2,"sec":"3.1 组成成分","title":"3.1 组成成分","notes":"毛发及体内组织的表皮\n中，如白细胞、血管内皮、成纤维细胞等\n神经胶质蛋白：神经胶质细胞\n不同种类的中间纤维有很强的组织特异性\n【结合课本/笔记】●细胞外被与细胞外基质第一节            细胞质膜与细胞表面特化结构细胞质膜(plasma membrane),又称细胞膜(cell membrane)。细胞内膜(intracellular membrane); 生物膜(biomembrane)● 细胞质膜的结构模型● 膜脂——生物膜的基本组成成分● 膜蛋白● 确定膜蛋白方向的实验程序● 光脱色恢复技术● 分子生物学技术在膜蛋白研究上的应用●生物膜结构特征● 细胞质膜的功能● 膜骨架与细胞表面的特化结构","page":3,"level":"掌握","img":"assets/img/ch08/p003.jpg","anim":null,"fig":null,"points":["角蛋白(keratin): 上皮细胞，如表皮细胞衍生的指甲、","波形蛋白(vimentin): 间质细胞、中胚层来源的细胞","结蛋白(desmin): 肌细胞","神经丝蛋白(neurofilament protein): 神经元轴突","核纤层蛋白(lamin) ：各种类型细胞的细胞核"],"check":{"q":"中间纤维的组成蛋白具有组织特异性，下列对应关系正确的是？","o":["A. 神经胶质蛋白—上皮细胞；角蛋白—神经胶质细胞","B. 角蛋白—间质细胞；波形蛋白—上皮细胞","C. 核纤层蛋白—细胞质微丝；结蛋白—神经元","D. 结蛋白—肌细胞；神经丝蛋白—神经元轴突"],"a":"D","e":"中间纤维组分具组织特异性：角蛋白在上皮细胞，波形蛋白在间质/中胚层细胞，结蛋白在肌细胞，神经丝蛋白在神经元轴突，核纤层蛋白在细胞核。","oe":["神经胶质蛋白在神经胶质细胞，角蛋白在上皮细胞。","角蛋白在上皮细胞，波形蛋白在间质细胞，对应相反。","核纤层蛋白在细胞核，结蛋白在肌细胞。","结蛋白在肌细胞，神经丝蛋白在神经元轴突。"]},"cards":null,"mem":"角蛋白上皮，波形间质，结蛋白肌，胶质GFAP","big":"assets/img/ch08/big/p003.jpg","terms":[{"t":"角蛋白","en":"keratin","d":"上皮细胞中的中间纤维蛋白，是皮肤、毛发等的主要结构成分。"},{"t":"波形蛋白","en":"vimentin","d":"间充质来源细胞中的中间纤维蛋白。"},{"t":"结蛋白","en":"desmin","d":"肌细胞中的中间纤维蛋白，连接肌原纤维与细胞膜。"},{"t":"神经丝蛋白","en":"neurofilament protein","d":"神经轴突中的中间纤维蛋白。"},{"t":"核纤层蛋白","en":"lamin","d":"构成核纤层的中间纤维蛋白，衬于核内膜下。"}]},{"i":3,"sec":"3.1 组成成分","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• INTERMEDIATE FILAMENTS —— 中间纤维\n• CYTOPLASMIC / NUCLEAR —— 细胞质型 / 核型\n• keratins —— 角蛋白(上皮细胞)\n• vimentin and related —— 波形蛋白及相关(结缔组织/肌/胶质细胞)\n• neurofilaments —— 神经丝(神经细胞)\n• nuclear lamins —— 核纤层蛋白(所有动物细胞)\n【读图讲解】\n中间纤维分类树状图：先分细胞质(CYTOPLASMIC)与核(NUCLEAR)两类；细胞质类再分角蛋白(keratins，上皮)、波形蛋白(vimentin，结缔/肌/胶质)、神经丝(neurofilaments，神经)；核类为核纤层蛋白(lamin，动物细胞)。考点：各型中间纤维的组织特异分布。","page":4,"level":"掌握","img":"assets/img/ch08/p004.jpg","anim":null,"fig":null,"points":["INTERMEDIATEFILAMENTS","CYTOPLASMIC","NUCLEAR","vimentin and","keratins","neurofilaments","nuclear lamins","vimentin-related"],"check":{"q":"下列中间纤维类型与其主要分布组织对应正确的是？","o":["A. 角蛋白—上皮细胞","B. 波形蛋白—所有动物细胞的细胞核内","C. 神经丝—结缔组织","D. 核纤层蛋白—上皮细胞桥粒"],"a":"A","e":"中间纤维分胞质型与核型：角蛋白在上皮、波形蛋白在结缔/肌/胶质细胞、神经丝在神经细胞，核纤层蛋白位于核膜下。","oe":["A. 正确，角蛋白主要分布于上皮细胞。","B. 错误，波形蛋白在结缔、肌、胶质细胞胞质中。","C. 错误，神经丝分布于神经细胞，不是结缔组织。","D. 错误，核纤层蛋白位于核膜下，不在桥粒。"]},"cards":null,"mem":"中间纤维分胞质型与核型，含核纤层蛋白","big":"assets/img/ch08/big/p004.jpg"},{"i":4,"sec":"3.1 组成成分","title":"上皮细胞中的角蛋白纤维与桥粒","notes":"epithelial cells in\nculture.\nThe filaments in each\ncell are indirectly\nconnected to those of\nits neighbors by\ndesmosomes.\nA second protein (blue)\nhas been stained to\nreveal the location of\nthe cell boundaries.\n【中文讲解·对照课本/考点】\n考点：第三节 中间纤维 · 3.1 组成成分 ｜ 教材：第十章 细胞骨架 · 第三节 中间丝（教材 p221–226）\n• tachment proteins),将特定的细胞骨架成分(中间纤维或微丝)同连接复合体结合在一起 (desmoplakin)●跨膜连接的糖蛋白,其细胞内的部分与附着蛋白相连, 细胞外的部分与相邻细胞的跨膜连接糖蛋白相互作用或与胞外基质相互作用。(desmoglein, desmocollin)四、通讯连接●间隙连接：分布广泛，几乎所有的动物组织中都存在间隙连接。●神经细胞间的化学突触●存在于可兴奋细胞之间的细胞连接方式,\n\n【本页英文讲解】\n本页展示培养上皮细胞中的角蛋白纤维（keratin filaments）。关键术语：角蛋白、桥粒（desmosome，蓝染）。核心概念：相邻细胞的角蛋白纤维通过桥粒间接相连，形成贯穿细胞群的力学网络。考点：角蛋白属中间纤维，桥粒为细胞间连接，二者偶联使上皮组织抗机械张力，呼应教材机械支持功能。","page":5,"level":"掌握","img":"assets/img/ch08/p005.jpg","anim":null,"fig":null,"points":["上皮细胞中角蛋白纤维形成网络","相邻细胞的角蛋白纤维通过桥粒(desmosome)间接相连"],"check":{"q":"培养上皮细胞中相邻细胞的角蛋白纤维通过什么结构间接相连？","o":["A. 紧密连接","B. 间隙连接","C. 黏着斑","D. 桥粒（desmosome）"],"a":"D","e":"上皮细胞中的角蛋白纤维通过桥粒间接相连，形成贯穿细胞群的力学网络，使上皮组织能够抵抗机械张力。","oe":["A. 错误，紧密连接封闭间隙，不连接角蛋白纤维。","B. 错误，间隙连接介导通讯，不连接角蛋白纤维。","C. 错误，黏着斑连接细胞与基质，属微丝连接。","D. 正确，相邻细胞的角蛋白经桥粒间接相连。"]},"cards":null,"mem":"上皮角蛋白经桥粒与邻细胞相连","big":"assets/img/ch08/big/p005.jpg","terms":[{"t":"桥粒斑蛋白","en":"desmoplakin","d":"桥粒中把角蛋白纤维锚定到桥粒连接复合体的中间纤维结合蛋白。"}]},{"i":5,"sec":"3.1 组成成分","title":"中间纤丝的单体","notes":"在伸长的神经轴突神经细胞及神经胶质细胞（神经纤\n维、波形蛋白）中、肌细胞、皮肤的上皮细胞（角蛋\n白）中含量都很丰富。","page":6,"level":"掌握","img":"assets/img/ch08/p006.jpg","anim":null,"fig":null,"points":["中间纤维在伸长的神经轴突、神经胶质细胞中含量丰富(神经纤维蛋白、波形蛋白)","在肌细胞及皮肤上皮细胞(角蛋白)中也丰富"],"check":{"q":"皮肤上皮细胞中含量丰富的中间纤维是？","o":["A. 角蛋白","B. 波形蛋白","C. 神经纤维蛋白","D. 核纤层蛋白(lamin)"],"a":"A","e":"中间纤维在神经轴突神经细胞及神经胶质细胞、肌细胞、皮肤上皮细胞中丰富；其中皮肤上皮细胞富含角蛋白(keratin)。","oe":["皮肤上皮细胞富含角蛋白，正确。","波形蛋白多见于神经胶质等细胞。","神经纤维蛋白主要见于神经细胞。","核纤层蛋白位于核膜下，不是皮肤上皮主要IF。"],"basis":"皮肤的上皮细胞（角蛋白）中含量都很丰富"},"cards":null,"mem":"中间纤丝单体富含于轴突、胶质、肌与表皮","big":"assets/img/ch08/big/p006.jpg"}],"mcq":[],"judge":[{"id":"ch08_ajudge_4","modI":1,"q":"角蛋白(keratin): 上皮细胞，如表皮细胞衍生的指甲、","a":"对","e":"本页要点：角蛋白(keratin): 上皮细胞，如表皮细胞衍生的指甲、","kp":"ch08_s1_2","oe":["中间纤维为细胞提供机械强度支持，是其重要功能，表述正确。","若判错，则与中间纤维提供机械支撑这一功能不符。"]}],"fill":[{"id":"ch08_fill_1","modI":1,"q":"成熟肌细胞中的中间丝是______，上皮细胞的中间丝是______。","a":"结蛋白；角质蛋白","kp":"ch08_s1_5","oe":["成熟肌细胞中的中间丝，可将肌原纤维锚定于Z盘。","上皮细胞中的中间丝，构成细胞间机械支撑网络。"]},{"id":"ch08_fill_4","modI":1,"q":"中间纤维的分布具有严格的组织特异性，其中 主要存在于肌细胞中。","a":"结蛋白","kp":"ch08_s1_2","oe":["结蛋白主要存在于肌细胞，是肌细胞中间纤维特征性蛋白。"]}],"short":[],"calc":[],"term":[]},{"i":2,"name":"第三节 中间纤维 · 3.1 IF proteins are tissue-specific","slides":[{"i":6,"sec":"3.1 IF proteins are ","title":"3.1 IF proteins are tissue-specific","notes":"【结合课本/笔记】（五）Signal Transduction           （问答英文）ReceptorsDefinition: Any protein that specifically binds to another molecules tomediate cell-cell signaling, adhesion, endocytosis or other cellularprocess. Mostly commonly denotes a protein located in the plasma membraneor cytoplasm that is activated by binding a specific extrace\n【中文讲解·对照课本/考点】\n考点：第三节 中间纤维 · 3.1 IF proteins are tissue-specific ｜ 教材：第十章 细胞骨架 · 第三节 中间丝（教材 p221–226）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n\n【本页英文讲解】\n本页标题为“IF proteins are tissue-specific”，即中间纤维蛋白（IF proteins）具组织特异性。原文仅此标题。核心概念：不同组织表达不同IF蛋白，如上皮表达角蛋白、神经细胞表达神经丝。考点：组织特异性使IF成为鉴别肿瘤细胞组织来源的标志物，是本章高频考点。","page":7,"level":"掌握","img":"assets/img/ch08/p007.jpg","anim":null,"fig":null,"points":["中间纤维蛋白具有组织特异性，不同组织表达不同IF蛋白"],"check":{"q":"中间纤维蛋白具组织特异性，这一特点的临床意义是？","o":["A. 可作为细胞凋亡的检测指标","B. 可作为细胞周期的标志物","C. 可用于鉴别肿瘤细胞的组织来源","D. 可用于判断细胞的能量代谢水平"],"a":"C","e":"不同组织表达不同IF蛋白（如上皮表达角蛋白），组织特异性使IF成为鉴别肿瘤细胞组织来源的重要标志物。","oe":["A. 错误，IF用于组织来源鉴定，不是凋亡检测指标。","B. 错误，IF表达与细胞周期无直接对应关系。","C. 正确，组织特异性可鉴定肿瘤的组织来源。","D. 错误，IF不反映细胞的能量代谢水平。"]},"cards":null,"mem":"中间纤维蛋白组织特异，可作肿瘤鉴别标志","big":"assets/img/ch08/big/p007.jpg"},{"i":7,"sec":"3.1 IF proteins are ","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• synemin / desmuslin —— 联丝蛋白 / 桥粒联结蛋白\n• CP49 —— 晶状体蛋白 CP49\n• lamin A/C, B1, B2 —— 核纤层蛋白 A/C、B1、B2\n【读图讲解】\n表格(表10-2 中间丝蛋白类型与组织分布)：按 I~VI 及未归类列出酸性/中性角蛋白、vimentin、结蛋白(desmin)、GFAP、外周蛋白、神经丝蛋白、核纤层蛋白、巢蛋白(nestin)、联丝蛋白及各型组织分布。考点：角蛋白在上皮、核纤层在核膜、VI型在神经/肌。","page":8,"level":"掌握","img":"assets/img/ch08/p008.jpg","anim":null,"fig":null,"points":["表10-2中间丝蛋白的类型和组织分布","型别","中间丝种类","基因数","相对分子质量/×10°","组织分布","酸性角蛋白",">25"],"check":{"q":"根据中间丝蛋白的类型与组织分布，下列对应正确的是？","o":["A. 核纤层蛋白—核膜下","B. 角蛋白—神经细胞","C. 神经丝蛋白—上皮细胞","D. 结蛋白—上皮细胞"],"a":"A","e":"中间丝类型具有组织特异性：角蛋白在上皮、神经丝蛋白在神经细胞、结蛋白在肌细胞、核纤层蛋白位于核膜下。","oe":["A. 正确，核纤层蛋白位于核膜下方。","B. 错误，角蛋白分布于上皮，不是神经细胞。","C. 错误，神经丝蛋白分布于神经细胞，非上皮。","D. 错误，结蛋白分布于肌细胞，不在上皮。"]},"cards":null,"mem":"表10-2：I~VI型中间丝蛋白与组织分布","big":"assets/img/ch08/big/p008.jpg","terms":[{"t":"巢蛋白","en":"nestin","d":"神经前体（干细胞）中表达的VI类中间纤维蛋白，常作神经前体标志物。"}]},{"i":8,"sec":"3.1 IF proteins are ","title":"A. Neurofilaments in a nerve cell axon","notes":"B. Glial filaments in glial cells, showing that these\nintermediate filaments are smooth and have few cross-\nbridges.\nC. A cross section of an axon showing the regular side-to-side\nspacing of the neurofilaments, which greatly outnumber the\nMTs.\n【中文讲解·对照课本/考点】\n考点：第三节 中间纤维 · 3.1 IF proteins are tissue-specific ｜ 教材：第十章 细胞骨架 · 第三节 中间丝（教材 p221–226）\n• tachment proteins),将特定的细胞骨架成分(中间纤维或微丝)同连接复合体结合在一起 (desmoplakin)●跨膜连接的糖蛋白,其细胞内的部分与附着蛋白相连, 细胞外的部分与相邻细胞的跨膜连接糖蛋白相互作用或与胞外基质相互作用。(desmoglein, desmocollin)四、通讯连接●间隙连接：分布广泛，几乎所有的动物组织中都存在间隙连接。●神经细胞间的化学突触●存在于可兴奋细胞之间的细胞连接方式,\n\n【本页英文讲解】\n本页比较三种中间纤维：神经丝（neurofilaments）位于神经细胞轴突，胶质纤维（glial filaments）位于胶质细胞且光滑、少横桥（cross-bridges）；轴突横切面显示神经丝规则并排，数量远多于微管（MTs）。考点：不同细胞表达不同IF体现组织特异性，神经丝维持轴突机械强度。","page":9,"level":"掌握","img":"assets/img/ch08/p009.jpg","anim":null,"fig":null,"points":["神经轴突中的神经丝光滑、横桥少","神经丝数量远多于微管，具有规则的侧向间距"],"check":{"q":"关于神经丝（neurofilaments）与胶质纤维（glial filaments）的描述，正确的是？","o":["A. 二者均位于细胞核内","B. 前者位于神经细胞轴突，后者位于胶质细胞且光滑少横桥","C. 二者均为微管，具有动态不稳定性","D. 前者由角蛋白构成，后者由结蛋白构成"],"a":"B","e":"神经丝位于神经细胞轴突，胶质纤维位于胶质细胞且光滑、少横桥；轴突横切面显示神经丝数量远多于微管。","oe":["A. 错误，二者均为胞质中间纤维，不在核内。","B. 正确，神经丝在轴突，胶质纤维光滑少横桥。","C. 错误，二者是中间纤维，不是微管。","D. 错误，神经丝由神经丝蛋白构成，不是角蛋白。"]},"cards":null,"mem":"神经丝在轴突，胶质丝光滑少横桥","big":"assets/img/ch08/big/p009.jpg","terms":[{"t":"胶质纤维","en":"glial filaments","d":"神经胶质细胞中的中间纤维，光滑、横桥少。"}]}],"mcq":[],"judge":[],"fill":[],"short":[],"calc":[],"term":[]},{"i":3,"name":"第三节 中间纤维 · 3.2 中间纤维特点","slides":[{"i":9,"sec":"3.2 中间纤维特点","title":"3.2 中间纤维特点","notes":"humans, are encoded by more than 60 different\ngenes.\n组织来源；人体中50多种不同的IF蛋白基因, 其表\n达具严格组织特异性\n(IF types serves as a diagnostic tool in medicine)\nhave an intrinsic polarity.)\n【中文讲解·对照课本/考点】\n考点：第三节 中间纤维 · 3.2 中间纤维特点 ｜ 教材：第十章 细胞骨架 · 第三节 中间丝（教材 p221–226）\n• 化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页总结中间纤维特点：IF是化学异质类群，人类由60多个基因编码；分布有严格组织特异性，可用于鉴别肿瘤细胞组织来源（医学诊断工具）；IF不参与细胞运动（cell motility）；与微管、微丝不同，IF没有内在极性（no intrinsic polarity）。考点：以上为教材第十章IF性质核心内容。","page":10,"level":"掌握","img":"assets/img/ch08/p010.jpg","anim":null,"fig":null,"points":["IFs are a chemically heterogeneous group, in","IF分布有严格组织特异性，用于鉴别肿瘤细胞的","IF不参与细胞运动(cell motility)","IF没有明显极性(Unlike MTs or MFs, Ifs don’t"],"check":{"q":"关于中间纤维(IF)特点的叙述，正确的是？","o":["A. 由60多个基因编码，表达具严格组织特异性","B. 与微管一样具有内在极性","C. 直接参与细胞运动和伪足形成","D. 由单一微管蛋白tubulin聚合而成"],"a":"A","e":"IF是化学异质类群，人类由60多个基因编码，分布有严格组织特异性，可鉴别肿瘤组织来源；且无极性、不参与细胞运动。","oe":["正确，IF由60多个基因编码且组织特异表达。","错误，IF无内在极性，微管、微丝才有极性。","错误，IF不参与细胞运动，主要起机械支撑作用。","错误，IF是化学异质类群，不由单一tubulin组成。"]},"cards":null,"mem":"IF化学异质、组织特异、无极性、不参与运动","big":"assets/img/ch08/big/p010.jpg"}],"mcq":[],"judge":[],"fill":[],"short":[],"calc":[],"term":[]},{"i":4,"name":"第三节 中间纤维 · 3.3 中间纤维(IFs)的装配","slides":[{"i":10,"sec":"3.3 中间纤维(IFs)的装配","title":"3.3 中间纤维(IFs)的装配","notes":"蛋白单体组成的 (any particular IF contains\nproteins from only a single class of monomer)。\n两个中间纤维蛋白亚基对应α-螺旋区缠绕形成双股\nα超螺旋, 即40-50nm的杆部(rod-shaped), 装配为中\n间纤维的主干，氨基酸序列都相同\nα中间纤维各种蛋白的共同特征\n【结合课本/笔记】核纤层蛋白的分子结构及其与中间纤维蛋白的关系◆核纤层与中间纤维之间的共同点·两者均形成10nm纤维;·两者均能抵抗高盐和非离子去垢剂的抽提;·某些抗中间纤维蛋白的抗体能与核纤层发生交叉反应·LaminA和LaminC的cDNA克隆推导出核纤层蛋白的氨基酸顺序与中间纤维蛋白高度保守的α-螺旋区有很强的同源性, 说明核纤层蛋白是中间纤维蛋白.","page":11,"level":"掌握","img":"assets/img/ch08/p011.jpg","anim":null,"fig":null,"points":["任何一种特定的IF都是由某一种单一的中间纤维","中间纤维蛋白分子中部有一段α-螺旋区高度保守,"],"check":{"q":"关于中间纤维装配的叙述，正确的是？","o":["A. 一种IF由多种单体混合装配而成","B. 装配主干由球形单体堆叠而成","C. 两个亚基的α-螺旋区缠绕形成双股α超螺旋","D. 核纤层蛋白与IF蛋白无任何同源性"],"a":"C","e":"任何一种IF只含单一类单体；两亚基对应α-螺旋区缠绕成双股α超螺旋，构成40–50nm杆状主干；核纤层蛋白与IF高度同源。","oe":["错误，任何一种IF只由单一类单体装配而成。","错误，IF单体为纤维状蛋白，不是球形单体。","正确，两亚基α-螺旋区缠绕成双股α超螺旋构成主干。","错误，核纤层蛋白与IF蛋白高度保守区同源。"]},"cards":null,"mem":"单一类单体组成，中部α螺旋成杆，最保守","big":"assets/img/ch08/big/p011.jpg"},{"i":11,"sec":"3.3 中间纤维(IFs)的装配","title":"A model of intermediate filament construction","notes":"【结合课本/笔记】·纤毛运动机制三、中间纤维（intermediate filament,IF)10nm纤维,因其直径介于肌粗丝和细丝之间, 故被命名为中间纤维。IF几乎分布于所有动物细胞，往往形成一个网络结构，特别是在需要承受机械压力的细胞中含量相当丰富。如上皮细胞中。除了胞质中，在内核膜下的核纤层也属于IF。●中间纤维的装配●中间纤维的成分与分布●中间纤维结合蛋白（ IFAP ）及其判定标准●中间纤维的功能中间纤维的装配◆中间纤维装配过程◆IF装配与MF,MT装配相比，有以下几个特点：·IF装配的单体是纤维状蛋白(MF,MT的单体呈球形)；·反向平行的四聚体导致IF不具有极性；·IF在体外装配时不需要核苷酸或结合蛋白的辅助，在体内装配后，细胞中几\n\n【本页英文讲解】\n本页标题为“A model of intermediate filament construction”（中间纤维组装模型），原文仅标题。核心概念：两个IF蛋白分子平行形成二聚体（dimer），两个二聚体反平行（antiparallel）缔合成四聚体（tetramer），四聚体是组装基本单位。考点：反平行缔合是IF无极性（no polarity）的结构基础。","page":12,"level":"掌握","img":"assets/img/ch08/p012.jpg","anim":null,"fig":null,"points":["中间纤维由单体经二聚体、四聚体等阶段组装而成"],"check":{"q":"中间纤维组装的基本亚单位（四聚体）是如何形成的？","o":["A. 两条单体反向平行形成二聚体","B. 两条单体同向平行形成二聚体","C. 两个异源二聚体首尾相连而成","D. 两个二聚体反向平行缔合成四聚体"],"a":"D","e":"两个IF蛋白分子平行形成二聚体，两个二聚体以反向平行方式缔合成四聚体，四聚体是中间纤维组装的基本亚单位。","oe":["A. 错误，二聚体由两条单体同向平行形成。","B. 错误，二聚体是同向平行，不是反向平行。","C. 错误，四聚体由两个二聚体反平行缔合形成。","D. 正确，两个二聚体反平行缔合成四聚体。"]},"cards":null,"mem":"中间纤维装配：二聚体→四聚体→原纤维","big":"assets/img/ch08/big/p012.jpg","terms":[{"t":"四聚体","en":"tetramer","d":"两个二聚体以反平行方式缔合成的IF装配单位；因两二聚体指向相反而无极性。"}]},{"i":12,"sec":"3.3 中间纤维(IFs)的装配","title":"两个相邻IF蛋白亚基的对应α-螺旋区形成双股α超螺旋","notes":"α二聚体\n2个超螺旋二聚体以反向平行的交错方式排列，组装成\n1个四聚体(tetramer) ；但由于两个二聚体的指向相反，\n四聚体本身则没有了极性。\n若干个四聚体（中间纤维装配的基本亚单位）相接组\n成原纤维(protofilament)，最终组装成中间纤维蛋白多\n聚体","page":13,"level":"掌握","img":"assets/img/ch08/p013.jpg","anim":null,"fig":null,"points":["两个相邻IF蛋白亚基的对应α-螺旋区形成双股α超螺旋(α二聚体)","2个超螺旋二聚体以反向平行的交错方式排列成1个四聚体(tetramer)","因两个二聚体指向相反，四聚体本身失去极性"],"check":{"q":"中间纤维四聚体不具极性的结构原因是？","o":["A. 单体呈球形，本身无方向性","B. 组装过程消耗ATP改变了方向","C. 两个二聚体以反向平行方式排列，指向相反","D. 四聚体由三条单体随机缠绕而成"],"a":"C","e":"IF单体为纤维状蛋白，两个二聚体以反向平行的交错方式缔合成四聚体，因二者指向相反使四聚体本身失去极性。","oe":["A. 错误，IF单体是纤维状蛋白，呈球形的是MF、MT。","B. 错误，IF组装不需核苷酸，无极性与此无关。","C. 正确，二聚体反平行排列使四聚体无极性。","D. 错误，四聚体由两个二聚体组成，不是三条单体。"]},"cards":null,"mem":"两二聚体反向平行成四聚体，故IF无极性","big":"assets/img/ch08/big/p013.jpg"},{"i":13,"sec":"3.3 中间纤维(IFs)的装配","title":"Structure and assembly of intermediate.","notes":"Tetramers aggregate end to end and laterally into a protofibril.\nIn a mature filament, consisting of four protofibrils, the globular domains form\nbeaded.\n【中文讲解·对照课本/考点】\n考点：第三节 中间纤维 · 3.3 中间纤维(IFs)的装配 ｜ 教材：第十章 细胞骨架 · 第三节 中间丝（教材 p221–226）\n• ·纤毛运动机制三、中间纤维（intermediate filament,IF)10nm纤维,因其直径介于肌粗丝和细丝之间, 故被命名为中间纤维。IF几乎分布于所有动物细胞，往往形成一个网络结构，特别是在需要承受机械压力的细胞中含量相当丰富。如上皮细胞中。除了胞质中，在内核膜下的核纤层也属于IF。●中间纤维的装配●中间纤维的成分与分布●中间纤维结合蛋白（ IFAP ）及其判定标准●中间纤维的功能中间纤维的装配◆中间纤维装配过程◆IF装配与MF,MT装配相比，有以下几个特点：·I\n\n【本页英文讲解】\n本页讲中间纤维结构与组装。术语：四聚体（tetramers）、原纤维（protofibril）、成熟纤维、球形结构域（globular domains）。核心机制：四聚体首尾相连并侧向聚集形成原纤维；成熟纤维由四条原纤维组成，球形域排列成念珠状。考点：组装层次为二聚体→四聚体→原纤维→纤维，IF组装不需ATP、无极性。","page":14,"level":"掌握","img":"assets/img/ch08/p014.jpg","anim":null,"fig":null,"points":["四聚体首尾相接并侧向聚集形成原纤维(protofibril)","成熟中间纤维由4条原纤维组成，球状结构域形成串珠状"],"check":{"q":"中间纤维的组装层次依次是？","o":["A. 二聚体→四聚体→原纤维→成熟纤维","B. 单体→微管→原纤维→成熟纤维","C. 三聚体→原纤维→微管→成熟纤维","D. 四聚体→二聚体→原纤维→成熟纤维"],"a":"A","e":"中间纤维组装为二聚体→四聚体→原纤维→成熟纤维；成熟纤维由四条原纤维组成，球形域排列成念珠状，组装不需ATP且无极性。","oe":["A. 正确，二聚体、四聚体、原纤维、成熟纤维。","B. 错误，中间纤维不由单体直接聚合为微管。","C. 错误，基本单位是二聚体，不存在三聚体阶段。","D. 错误，顺序颠倒，应为二聚体先于四聚体。"]},"cards":null,"mem":"四聚体端端侧向聚成原纤维，4根成珠状丝","big":"assets/img/ch08/big/p014.jpg","terms":[{"t":"原纤维","en":"protofilament / protofibril","d":"由四聚体首尾相接、侧向聚集形成的线状结构，是中间纤维的组成单位。"}]},{"i":14,"sec":"3.3 中间纤维(IFs)的装配","title":"中间纤维的动态装配特点","notes":"中间纤维的动态装配特点：细胞内几乎没有游离的IF单体，但IF仍是细胞内动态的多聚体。","page":15,"level":"掌握","img":"assets/img/ch08/p015.jpg","anim":null,"fig":null,"points":["游离的单体很少，蛋白合成后基本全组装成中间纤","但在某些细胞中，中间纤维装配/去装配是动态的","不表现典型的脚踏车行为，也不需要ATP/GTP参与。"],"check":{"q":"关于中间纤维动态装配特点的叙述，正确的是？","o":["A. 细胞内游离的IF单体数量很多","B. 不表现典型脚踏车行为，也不需要ATP/GTP","C. 必须水解ATP才能完成装配","D. IF是静态结构，从不组装去组装"],"a":"B","e":"细胞内游离IF单体极少，合成后基本全部组装；但在某些细胞中IF仍是动态多聚体，装配不表现典型脚踏车行为，也不需要ATP/GTP。","oe":["错误，细胞内游离IF单体极少，多已组装。","正确，IF装配不呈脚踏车且不需ATP/GTP参与。","错误，IF装配不需要ATP或GTP参与。","错误，某些细胞中IF仍为动态多聚体。"]},"cards":null,"mem":"游离单体极少，无踏车，不需ATP/GTP","big":"assets/img/ch08/big/p015.jpg"}],"mcq":[{"id":"ch08_mcq_1","mod":"3.3 中间纤维(IFs)的装配","modI":4,"q":"核纤层蛋白从氨基酸序列的同源比较上看，属于（            ）。","o":["A．微管","B．微丝","C．中间丝","D．核骨架蛋白"],"a":"C","e":"近年来发现核纤层与中间丝有许多共同点，通过对核纤层蛋白的 cDNA 克隆的研 究，并与中间丝的氨基酸序列对比，说明核纤层蛋白确实是中间丝蛋白家族成员。","kp":"ch08_s4_10","oe":["核纤层蛋白不属于微管蛋白，序列同源比较与之不符。","核纤层蛋白不属于微丝蛋白，也不是肌动蛋白。","正确——氨基酸序列同源比较表明核纤层蛋白属中间丝蛋白家族。","核骨架蛋白是功能分类，并非按序列同源比较的归属。"]}],"judge":[{"id":"ch08_judge_1","modI":4,"q":"中间纤维蛋白合成后，基本上均组装为中间纤维，没有大量游离的单体存在。（                           ）","a":"对","e":"","kp":"ch08_s4_14","oe":["中间纤维蛋白合成后大多迅速组装成纤维，细胞内几乎无游离单体库。","若判错，则忽视中间纤维高度组装、无显著游离单体池的特点。"]}],"fill":[{"id":"ch08_fill_2","modI":4,"q":"中间丝的组装过程可以简要概括为______。","a":"形成双股螺旋的二聚体→组成反向半重叠的四聚体→形成原纤丝→形成中间纤维","kp":"ch08_s4_14","oe":["两条多肽形成双股螺旋二聚体，再反平行组成四聚体，进而形成原纤丝和纤维。"]}],"short":[{"id":"ch08_short_3","modI":4,"q":"微管和微丝这两种细胞骨架系统在细胞中都有一个巨大的蛋白库，但中间纤维系统却只 有很少的游离的组分，这是为什么？","a":"微管和微丝在细胞中都有一个巨大的蛋白库，但中间纤维系统却只有很少的游离的组分， 这主要与微管、微丝和中间纤维在组装和存在方式上的差异有关。 （1）微管和微丝都处于动态平衡状态，不停地组装和去组装，所以在细胞中含有一个巨大 的蛋白库。 （2）不同来源的组织细胞表达不同的中间纤维类型，通常在各自的细胞内形成同源多聚体， 中间纤维在合适的缓冲体系中能自我组装，而且组装过程中不需要 ATP 或 GTP 提供能量。 中间纤维的组装首先由两个单体的杆状区以平行排列的方式形成双股螺旋的二聚体，然后两 个二聚体以反向平行和半分子交错的形式组装成四聚体。四聚体是细胞质中中间纤维组装的 最小结构单位，对四聚体而言，没有极性。细胞内的新的中间纤维可以通过交换的方式插入 到原有的纤维中去，因此在细胞中不需要有大量的游离组分。","kp":"ch08_s4_14"}],"calc":[],"term":[]},{"i":5,"name":"第三节 中间纤维 · 3.4 中间纤维结合蛋白","slides":[{"i":15,"sec":"3.4   中间纤维结合蛋白","title":"3.4   中间纤维结合蛋白","notes":"间纤维与其它细胞结构的相互作用。\n如Plectin(网蛋白)，大多数细胞中有其表达，将波形蛋白\nvimentin纤维集结成束，还能使中间丝与微管、微丝交联在一起，\n形成横桥。\n【结合课本/笔记】·纤毛运动机制三、中间纤维（intermediate filament,IF)10nm纤维,因其直径介于肌粗丝和细丝之间, 故被命名为中间纤维。IF几乎分布于所有动物细胞，往往形成一个网络结构，特别是在需要承受机械压力的细胞中含量相当丰富。如上皮细胞中。除了胞质中，在内核膜下的核纤层也属于IF。●中间纤维的装配●中间纤维的成分与分布●中间纤维结合蛋白（ IFAP ）及其判定标准●中间纤维的功能中间纤维的装配◆中间纤维装配过程◆IF装配与MF,MT装配相比，有以下几个特点：·IF装配的单体是纤维状蛋白(MF,MT的单体呈球形)；·反向平行的四聚体导致IF不具有极性；·IF在体外装配时不需要核苷酸或结合蛋白的辅助，在体内装配后，细胞中几","page":16,"level":"掌握","img":"assets/img/ch08/p016.jpg","anim":null,"fig":null,"points":["在细胞内与中间纤维(IFs)共分布, 介导IFs之间以及中"],"check":{"q":"关于中间纤维结合蛋白(IFAP)的叙述，正确的是？","o":["A. IFAP只存在于上皮细胞且与分化无关","B. 网蛋白只能交联微管与微丝，不能连接中间丝","C. IFAP的判定标准是能水解ATP供能","D. 网蛋白可将波形蛋白纤维集束并与微管微丝交联"],"a":"D","e":"网蛋白(plectin)广泛表达，可把波形蛋白纤维集结成束，并把中间丝与微管、微丝交联成横桥；IFAP在细胞内与IF共分布，介导IF之间的相互作用。","oe":["错误，IFAP分布广泛，与细胞分化密切相关。","错误，网蛋白正是把中间丝与微管微丝交联。","错误，判定看其与IF共分布并介导相互作用。","正确，Plectin使vimentin成束并交联微管与微丝。"]},"cards":null,"mem":"网蛋白plectin交联中间丝与微管、微丝","big":"assets/img/ch08/big/p016.jpg","terms":[{"t":"网蛋白","en":"plectin","d":"把中间纤维与其他骨架成分及连接结构交联的中间纤维结合蛋白。"}]}],"mcq":[],"judge":[{"id":"ch08_ajudge_8","modI":5,"q":"在细胞内与中间纤维(IFs)共分布, 介导IFs之间以及中","a":"对","e":"本页要点：在细胞内与中间纤维(IFs)共分布, 介导IFs之间以及中","kp":"ch08_s5_15","oe":["桥粒斑蛋白等与中间纤维共分布，介导IFs间及其与膜结构的连接。","若判错，则这类连接蛋白确实介导中间纤维间的连接，否定无据。"]}],"fill":[{"id":"ch08_fill_3","modI":5,"q":"与微管、微丝不同，中间纤维的装配不具有______。中间纤维的分布具有严格的______。","a":"极性；组织特异性。","kp":"ch08_s5_15","oe":["中间丝由反向平行四聚体组装，两端对称，故无极性。","不同类型中间丝蛋白分布不同组织，具严格组织特异性。"]}],"short":[{"id":"ch08_short_2","modI":5,"q":"为什么说中间丝具有异质性？","a":"中间丝具有多种类型，不同类型的中间丝蛋白其化学组成不同，主要表现在非α螺旋的 头部和尾部这两个结构域序列多变，长度相差甚远，在中间丝的组装过程中发挥重要的作用。","kp":"ch08_s5_15"}],"calc":[],"term":[]},{"i":6,"name":"第三节 中间纤维 · 3.5 中间纤维的功能","slides":[{"i":16,"sec":"3.5.1 为细胞提供机械强度支持(Co","title":"3.5 中间纤维的功能","notes":"3.5.1 为细胞提供机械强度支持(Confer mechanical strength\non tissues)\nDisruption of keratin networks causes blistering(起泡)\n【结合课本/笔记】·纤毛运动机制三、中间纤维（intermediate filament,IF)10nm纤维,因其直径介于肌粗丝和细丝之间, 故被命名为中间纤维。IF几乎分布于所有动物细胞，往往形成一个网络结构，特别是在需要承受机械压力的细胞中含量相当丰富。如上皮细胞中。除了胞质中，在内核膜下的核纤层也属于IF。●中间纤维的装配●中间纤维的成分与分布●中间纤维结合蛋白（ IFAP ）及其判定标准●中间纤维的功能中间纤维的装配◆中间纤维装配过程◆IF装配与MF,MT装配相比，有以下几个特点：·IF装配的单体是纤维状蛋白(MF,MT的单体呈球形)；·反向平行的四聚体导致IF不具有极性；·IF在体外装配时不需要核苷酸或结合蛋白的辅助，在体内装配后，细胞中几\n\n【本页英文讲解】\n本页讲3.5中间纤维功能，首要功能是为细胞提供机械强度支持（confer mechanical strength on tissues）。例证：角蛋白网络（keratin networks）被破坏会导致皮肤起泡（blistering）。考点：这是IF功能最经典证据，如角蛋白突变引起单纯型大疱性表皮松解症，说明IF赋予上皮抗机械应激能力。","page":17,"level":"掌握","img":"assets/img/ch08/p017.jpg","anim":null,"fig":null,"points":["中间纤维为细胞提供机械强度支持","角蛋白网络破坏会导致皮肤起泡(blistering)"],"check":{"q":"中间纤维破坏导致皮肤起泡，说明其首要功能是？","o":["A. 参与胞内物质的长距离运输","B. 为细胞和组织提供机械强度支持","C. 作为马达蛋白运动的轨道","D. 参与纺锤体的形成"],"a":"B","e":"中间纤维的首要功能是为细胞和组织提供机械强度支持，角蛋白网络被破坏会导致皮肤起泡（如大疱性表皮松解症）。","oe":["A. 错误，长距离运输是微管的功能，不是中间纤维。","B. 正确，IF为细胞和组织提供机械强度支持。","C. 错误，中间纤维没有马达蛋白，不作为轨道。","D. 错误，纺锤体由微管构成，与IF无关。"]},"cards":null,"mem":"中间纤维提供机械强度，角蛋白破坏致起泡","big":"assets/img/ch08/big/p017.jpg"},{"i":17,"sec":"3.5.1 为细胞提供机械强度支持(Co","title":"单根中间纤维的机械性能","notes":"before and after it has been subjected to mechnical forces.\nThis segment has been streched more than 3 times its original\nlenghth. (from 280nm to a stretched length of 500+450nm)\nThe stretch segment is thinner than the unstretched sections,\nsuggests that the subunits may be capable of sliding over one\nanother as the filament is being pulled. (2005)\n【中文讲解·对照课本/考点】\n考点：第三节 中间纤维 · 3.5 中间纤维的功能 ｜ 教材：第十章 细胞骨架 · 第三节 中间丝（教材 p221–226）\n• ·纤毛运动机制三、中间纤维（intermediate filament,IF)10nm纤维,因其直径介于肌粗丝和细丝之间, 故被命名为中间纤维。IF几乎分布于所有动物细胞，往往形成一个网络结构，特别是在需要承受机械压力的细胞中含量相当丰富。如上皮细胞中。除了胞质中，在内核膜下的核纤层也属于IF。●中间纤维的装配●中间纤维的成分与分布●中间纤维结合蛋白（ IFAP ）及其判定标准●中间纤维的功能中间纤维的装配◆中间纤维装配过程◆IF装配与MF,MT装配相比，有以下几个特点：·I\n\n【本页英文讲解】\n本页展示单根中间纤维受力前后的力学性质：拉伸后片段被拉长3倍以上，由280nm伸长到500+450nm；被拉伸处比未拉伸处更细，提示纤维受拉时亚单位（subunits）间可能相互滑动。考点：IF具高延展性和弹性，亚单位滑动是主要变形机制，与其抗机械张力功能相符。","page":18,"level":"掌握","img":"assets/img/ch08/p018.jpg","anim":null,"fig":null,"points":["单个中间纤维可被拉伸超过原长的3倍(280nm→500+450nm)","拉伸段变细，说明亚基之间能相互滑动"],"check":{"q":"单根中间纤维被拉伸3倍以上且拉伸段变细，提示其变形机制是？","o":["A. 纤维被拉断成两段","B. 亚基被降解","C. 亚基之间可相互滑动","D. 纤维被重新组装"],"a":"C","e":"中间纤维被拉长3倍以上后拉伸段变细，提示其亚基在纤维受拉时可相互滑动，这赋予中间纤维很强的延展性和机械强度。","oe":["纤维并未被拉断，而是可逆地延长变细。","拉伸过程中中间纤维的亚基并未被降解。","拉伸段变细提示亚基相互滑动，正确。","这是受力后的可逆变形，并非纤维重新组装。"],"basis":"中间纤维亚基可能相互滑动"},"cards":null,"mem":"单根中间纤维可拉伸3倍长，极具弹性","big":"assets/img/ch08/big/p018.jpg"}],"mcq":[],"judge":[],"fill":[],"short":[],"calc":[],"term":[]},{"i":7,"name":"第三节 中间纤维 · 3.5.2 参与细胞连接 (桥粒、半桥粒)","slides":[{"i":18,"sec":"3.5.2 参与细胞连接 (桥粒、半桥粒","title":"3.5.2 参与细胞连接 (桥粒、半桥粒)","notes":"拉时能经受机械力的作用。在3类细胞骨架成分中最为坚韧和\n耐久，赋予细胞机械强度。\n3.5.3 维持细胞核膜的稳定\n白是中间纤维的一种。","page":19,"level":"掌握","img":"assets/img/ch08/p019.jpg","anim":null,"fig":null,"points":["中间纤维有很强的抗拉强度，主要功能就是使细胞在牵","细胞核内膜下面有一层由核纤层蛋白组成的网络，核纤层蛋"],"check":{"q":"中间纤维在细胞连接与机械支持中的主要功能是？","o":["A. 直接产生收缩力驱动细胞运动","B. 参与桥粒、半桥粒连接，赋予细胞机械强度","C. 作为纺锤体主要成分牵引染色体","D. 催化ATP合成，为细胞供能"],"a":"B","e":"在3类细胞骨架中IF最为坚韧耐久，通过桥粒、半桥粒参与细胞连接，使细胞在牵拉时能承受机械力，赋予细胞机械强度。","oe":["错误，产生收缩力的是微丝与肌球蛋白。","正确，IF通过桥粒半桥粒使细胞承受机械力。","错误，纺锤体主要成分是微管而非中间纤维。","错误，IF是结构蛋白，不催化ATP合成。"]},"cards":null,"mem":"中间纤维连桥粒/半桥粒，并维持核膜稳定","big":"assets/img/ch08/big/p019.jpg"},{"i":19,"sec":"3.5.2 参与细胞连接 (桥粒、半桥粒","title":"核纤层(nuclear lamina)","notes":"●增强了核膜的机械强度；\n●对细胞核从分裂期到间期时的重建有重要作用；\n●为染色质提供锚定位点，介导大的染色体环形成。\n【结合课本/笔记】●核体（nuclear bodies，NBs）核基质(nuclear matrix)●核基质或核骨架(nuclear skeleton)的概念●狭义概念仅指核基质，即细胞核内除了核被膜、核纤层、染色质与核仁以外的网架结构体系。●广义概念应包括核基质、核纤层(或核纤层-核孔复合体结构体系),以及染色体骨架。●目前对核骨架的研究结论●核骨架是存在于真核细胞核内真实的结构体系；●核骨架与核纤层、中间纤维相互连接形成贯穿于核与质的一个独立结构系统。●核骨架的主要成分是由非组蛋白的纤维蛋白构成的, 含有多种蛋白成分及少量RNA；●核骨架与DNA复制、基因表达及染色体的包装与构建有密切关系。","page":20,"level":"掌握","img":"assets/img/ch08/p020.jpg","anim":null,"fig":null,"points":["位于细胞核内层核膜下方的纤维蛋白网络","组成蛋白：哺乳类和鸟类细胞","LaminA","LaminB","LaminC","作用"],"check":{"q":"关于核纤层(nuclear lamina)，下列叙述正确的是？","o":["A. 位于核膜内层下方，由lamin蛋白构成纤维网络","B. 由肌动蛋白和肌球蛋白构成","C. 位于质膜下方，形成收缩环","D. 由微管蛋白聚合而成"],"a":"A","e":"核纤层是位于细胞核内层核膜下方的纤维蛋白网络，组成蛋白为Lamin A、B、C，可增强核膜机械强度，并参与核膜重建与染色质锚定。","oe":["核纤层位于内层核膜下方，由lamin构成，正确。","肌动蛋白和肌球蛋白构成的是收缩环等。","收缩环位于质膜下，与核纤层位置不同。","核纤层属于中间纤维，并不是微管聚合而成。"],"basis":"核内层核膜下方纤维蛋白网络；Lamin A/B/C"},"cards":null,"mem":"核纤层=A/B/C型lamin，撑核膜、锚染色质","big":"assets/img/ch08/big/p020.jpg"},{"i":20,"sec":"3.5.2 参与细胞连接 (桥粒、半桥粒","title":"中间纤维的特点","notes":"染色质之间.\n的骨架体系。\n【结合课本/笔记】·纤毛运动机制三、中间纤维（intermediate filament,IF)10nm纤维,因其直径介于肌粗丝和细丝之间, 故被命名为中间纤维。IF几乎分布于所有动物细胞，往往形成一个网络结构，特别是在需要承受机械压力的细胞中含量相当丰富。如上皮细胞中。除了胞质中，在内核膜下的核纤层也属于IF。●中间纤维的装配●中间纤维的成分与分布●中间纤维结合蛋白（ IFAP ）及其判定标准●中间纤维的功能中间纤维的装配◆中间纤维装配过程◆IF装配与MF,MT装配相比，有以下几个特点：·IF装配的单体是纤维状蛋白(MF,MT的单体呈球形)；·反向平行的四聚体导致IF不具有极性；·IF在体外装配时不需要核苷酸或结合蛋白的辅助，在体内装配后，细胞中几","page":21,"level":"掌握","img":"assets/img/ch08/p021.jpg","anim":null,"fig":null,"points":["纤维直径为10 nm左右, 网络结构分布于内核膜与","核纤层、中间纤维相互连接，贯穿细胞核/细胞质","核纤层蛋白(lamin)被定为第V型中间纤维蛋白","核纤层与核膜关系密切，增强核膜的机械强度。"],"check":{"q":"关于核纤层特点的叙述，正确的是？","o":["A. 直径约25nm，属于微管家族","B. 核纤层蛋白被定为第III型中间纤维","C. 分布于细胞质中，与核膜无关系","D. 纤维直径约10nm，被定为第V型中间纤维蛋白"],"a":"D","e":"核纤层纤维直径约10nm，网络位于内核膜与染色质之间，其lamin被定为第V型中间纤维蛋白，与核膜关系密切并增强核膜机械强度。","oe":["错误，25nm是微管直径，核纤层约10nm。","错误，核纤层蛋白被定为第V型中间纤维蛋白。","错误，核纤层位于内核膜与染色质之间。","正确，核纤层约10nm，lamin属第V型中间纤维。"]},"cards":null,"mem":"核纤层10nm，在内核膜与染色质间，属V型IF","big":"assets/img/ch08/big/p021.jpg"},{"i":21,"sec":"3.5.2 参与细胞连接 (桥粒、半桥粒","title":"细胞周期中核纤层的变化","notes":"对核膜的崩解/重装配有调节作用\n核纤层蛋白在细胞有丝分裂前期磷酸化有助于发动核层\n和核膜的解聚。末期的脱磷酸化，可以逆转上述过程。","page":22,"level":"掌握","img":"assets/img/ch08/p022.jpg","anim":null,"fig":null,"points":["核纤层对核膜的崩解/重装配有调节作用","有丝分裂前期核纤层蛋白磷酸化促进核纤层和核膜解聚","末期脱磷酸化逆转上述过程"],"check":{"q":"核纤层蛋白在细胞有丝分裂前期的磷酸化作用是？","o":["A. 促进核糖体的组装","B. 启动DNA复制","C. 促进染色体凝集","D. 有助于核纤层和核膜的解聚"],"a":"D","e":"有丝分裂前期核纤层蛋白磷酸化，发动核纤层和核膜的解聚；末期脱磷酸化则可逆转该过程，有利于核膜重装配。","oe":["A. 错误，核纤层蛋白磷酸化与核糖体组装无关。","B. 错误，DNA复制在S期，与核纤层解聚无直接关系。","C. 错误，染色体凝集由凝缩蛋白复合物介导。","D. 正确，磷酸化发动核纤层和核膜的解聚。"]},"cards":null,"mem":"前期lamin磷酸化解聚，末期脱磷酸化重装","big":"assets/img/ch08/big/p022.jpg"},{"i":22,"sec":"3.5.2 参与细胞连接 (桥粒、半桥粒","title":"•间期","notes":"The nuclear envelope\nbreaks down and\nreforms during mitosis.\n【结合课本/笔记】细胞周期长短测定◆脉冲标记DNA复制和细胞分裂指数观察测定法◆流式细胞仪测定法(Flow Cytometry)◆缩时摄像技术，可以得到准确的细胞周期时间及分裂间期和分裂期的准确时间。细胞周期同步化◆自然同步化，如有一种粘菌的变形体plasmodia，某些受精卵早期卵裂◆人工选择同步化◆药物诱导法◆条件依赖性突变株在细胞周期同步化中的应用：将与细胞周期调控有关的条件依赖性突变株转移到限定条件下培养，所有细胞便被同步化在细胞周期中某一特定时期。人工选择同步化·有丝分裂选择法：用于单层贴壁生长细胞。优点是细胞未经任何药物处理，细胞同步化效率高。缺点是分离的细胞数量少。·密度梯度离心法：根据不同时期的细胞在体积和重量上存在差别进行分离。优点\n\n【本页英文讲解】\n本页示意核纤层（nuclear lamina）在细胞周期中的动态。原文：核被膜（nuclear envelope）在有丝分裂（mitosis）中解体并重新形成；标注间期（interphase）与有丝分裂期。核心概念：核纤层由中间纤维——核纤层蛋白（lamin）构成，分裂期磷酸化解聚使核被膜崩解，末期去磷酸化重建。考点：核纤层是特殊中间纤维。","page":23,"level":"掌握","img":"assets/img/ch08/p023.jpg","anim":null,"fig":null,"points":["有丝分裂期"],"check":{"q":"细胞周期中核纤层的动态变化是？","o":["A. 分裂期核纤层蛋白去磷酸化，核被膜解体","B. 核纤层在整个细胞周期中始终完整不变","C. 分裂期核纤层蛋白磷酸化解聚，核被膜崩解","D. 间期核纤层解聚，分裂期重新组装"],"a":"C","e":"核纤层由lamin构成，有丝分裂期lamin磷酸化解聚导致核被膜崩解，末期去磷酸化后核被膜重新形成。","oe":["错误，分裂期是磷酸化，末期才去磷酸化。","错误，核纤层在分裂期解聚，末期重建。","正确，分裂期lamin磷酸化解聚致核被膜崩解。","错误，间期核纤层完整，分裂期解聚。"]},"cards":null,"mem":"核膜随有丝分裂崩解与重建","big":"assets/img/ch08/big/p023.jpg"}],"mcq":[],"judge":[],"fill":[],"short":[{"id":"ch08_short_1","modI":7,"q":"简述中间纤维的形态和分类。","a":"（1）中间纤维是一类蛋白质纤维系统，呈中空管状结构，其直径介于微管和微丝之间， 约为 19nm。 （2）中间纤维具有种属和组织特异性，根据其组织特异性的不同主要分为 5 类：①角质蛋 白纤维；②神经纤维蛋白；③结蛋白；④胶质纤维酸性蛋白；⑤波形纤维蛋白。","kp":"ch08_s7_18"}],"calc":[],"term":[{"id":"ch08_term_1","modI":7,"term":"细胞骨架（cytoskeleton）。","def":"细胞骨架（cytoskeleton）是指细胞中的蛋白纤维网架体系，包括微丝、微管和中间丝。 细胞骨架是一种高度动态的结构体系。其主要功能有结构与支持作用；胞内运输作用；收缩 与运动；空间组织。","kps":"","kp":"ch08_s7_19"},{"id":"ch08_term_2","modI":7,"term":"cytoskeleton","def":"cytoskeleton 的中文名称是细胞骨架。细胞骨架是指用电子显微镜观察经非离子去污剂 处理后的细胞，可以在细胞质内观察到一个复杂的纤维状三维网络结构体系，包括微丝、微 管和中间纤维。细胞骨架为真核细胞所特有，它不仅是活细胞的支撑结构，决定细胞的形状 并赋予其强度，而且在细胞多种多样的生理活动（如细胞运动、膜泡运输和细胞分裂等）中 发挥着重要作用。","kps":"","kp":"ch08_s7_19"}]},{"i":8,"name":"第三节 中间纤维 · 3.5.4 表达有组织特异性，与细胞分化关系密切","slides":[{"i":23,"sec":"3.5.4 表达有组织特异性，与细胞分化","title":"3.5.4 表达有组织特异性，与细胞分化关系密切","notes":"不同的中间纤维在各类组织中有特异表达，表明与\n细胞分化有密切关系。(微管、微丝在各种细胞中\n均为一种组成蛋白tubulin/actin)\n●胚胎发育 eg.小鼠   8-9天 角蛋白表达下降并停止;\n(vimentin)→神经元纤维蛋白(neurofilament)\n●上皮分化\n碱性角蛋白)表达有特异性。\nα细胞的不同分化时期有不同的中间纤维蛋白基因表达\n\n【本页讲解】\n本页讲中间纤维（IF）的组织特异性及其与细胞分化的关系。与微管（组成蛋白只有 tubulin）、微丝（只有 actin）不同，中间纤维成分复杂，不同组织表达不同的 IF 蛋白，因此是细胞分化的重要标志。要点一【胚胎发育】：小鼠胚胎 8–9 天时角蛋白（keratin）表达下降并停止；将发育为神经细胞的细胞，其 IF 蛋白按“角蛋白→波形纤维蛋白（vimentin）→神经元纤维蛋白（neurofilament）”的顺序依次替换，说明胚胎细胞能根据发育方向调节 IF 基因表达。要点二【上皮分化】：上皮分化中不同角蛋白（酸性角蛋白 + 中性-碱性角蛋白）成对特异性表达。结论：同一细胞在不同分化时期表达不同的中间纤维蛋白基因，这正是 IF 表达具组织特异性的分子基础。","page":24,"level":"掌握","img":"assets/img/ch08/p024.jpg","anim":null,"fig":null,"points":["最初胚胎细胞中表达角蛋白      同时波形纤维蛋白表达","将发育为神经细胞的细胞: 角蛋白(keratin)→波形纤维蛋白","胚胎细胞能根据其发育方向调节中间纤维蛋白基因的表达","上皮细胞分化过程中不同类型的角蛋白(酸性角蛋白&中性-"],"check":{"q":"关于中间纤维表达与细胞分化的关系，正确的是？","o":["A. 微管和微丝的组成蛋白在不同细胞中差异极大","B. 所有组织的中间纤维蛋白种类完全相同","C. 胚胎细胞IF按角蛋白、波形纤维蛋白、神经丝顺序替换","D. IF表达与细胞分化无直接关系"],"a":"C","e":"与微管(仅tubulin)、微丝(仅actin)不同，IF成分复杂且表达有组织特异性；将发育为神经细胞的IF按角蛋白、波形纤维蛋白、神经丝顺序替换，说明与分化关系密切。","oe":["错误，微管只有tubulin，微丝只有actin。","错误，不同组织表达的IF蛋白种类不同。","正确，神经方向分化时IF依此顺序替换。","错误，IF表达有组织特异性，与分化密切相关。"]},"cards":null,"mem":"胚胎角蛋白→波形→神经丝，随分化更换","big":"assets/img/ch08/big/p024.jpg","terms":[{"t":"组织特异性","en":"tissue-specific expression","d":"不同组织表达不同中间纤维蛋白（如上皮-角蛋白、肌-结蛋白），与细胞分化关系密切。"}]},{"i":24,"sec":"3.5.4 表达有组织特异性，与细胞分化","title":"本章小结","notes":"【中文讲解·对照课本/考点】\n考点：第三节 中间纤维 · 3.5.4 表达有组织特异性，与细胞分化关系密切 ｜ 教材：第十章 细胞骨架 · 第三节 中间丝（教材 p221–226）\n• 中间纤维的成分与分布IF成分比MF,MT复杂，具有组织特异性。IF在形态上相似，而化学组成有明显的差别。\n\n【本页讲解】\n本页是一张英文“Summary”对比表（Microfilaments 微丝 / Microtubules 微管 / Intermediate Filaments 中间纤维），逐行对比三大骨架：①与核苷酸结合——微丝 actin 结合 ATP；微管 αβ-tubulin 结合 GTP；中间纤维亚基不结合核苷酸。②形态与力学——微丝形成刚性凝胶、网络与线性束；微管刚硬、不易弯曲；中间纤维抗张强度最大。③组装位点——微丝在细胞内许多位点受调控组装；微管在少数位点（如 MTOC）受调控组装；中间纤维在已有纤维上延长组装。④动态性——微丝、微管高度动态，中间纤维动态性低。⑤极性——微丝、微管有极性，中间纤维无极性。⑥马达蛋白——微丝是肌球蛋白（myosin）的轨道，微管是驱动蛋白（kinesin）与动力蛋白（dynein）的轨道，中间纤维没有马达蛋白。⑦功能——微丝构成细胞皮层收缩机器与网络；微管负责细胞器的组织与长距离运输；中间纤维维持细胞与组织的机械完整性。","page":25,"level":"掌握","img":"assets/img/ch08/p025.jpg","anim":null,"fig":null,"points":["本章总结细胞骨架三大纤维的结构与功能"],"check":{"q":"根据三大细胞骨架的对比，下列说法正确的是？","o":["A. 中间纤维无极性、不结合核苷酸、无马达蛋白","B. 微丝无极性，而微管有极性","C. 微管的组装不需要GTP","D. 中间纤维高度动态，有明显动态不稳定性"],"a":"A","e":"对比三大骨架：微丝结合ATP、微管结合GTP、IF不结合核苷酸；微丝微管有极性，IF无极性；IF无马达蛋白、动态性低。","oe":["A. 正确，IF无极性、不结合核苷酸、无马达蛋白。","B. 错误，微丝和微管都具有极性。","C. 错误，β-tubulin结合GTP，微管组装需要GTP。","D. 错误，IF动态性低，明显动态不稳定的是微管。"]},"cards":null,"mem":"MF/MT/IF对比：成分、极性、动态、药物","big":"assets/img/ch08/big/p025.jpg"},{"i":25,"sec":"3.5.4 表达有组织特异性，与细胞分化","title":"微管   微丝   中间纤维","notes":"组成蛋白\n结合蛋白\n单体是否结合\nGTP/ATP\n是否具有极性\n动态不稳定性\n特异性药物\n马达蛋白\n主要生理功能\n【结合课本/笔记】●功能形态结构◆研究核骨架的分级抽提方法非离子去垢剂溶解膜结构系统,胞质中可溶性成分随之流失; 再用Tween40和脱氧胆酸钠处理,胞质中的微管、微丝与一些蛋白结构被溶去,胞质中只有中间纤维网能完好存留;然后用核酸酶与0.25mol/L硫酸铵处理,染色质中DNA、RNA和组蛋白被抽提, 最终核内呈现一个精细发达的核骨架网络, 结合非树脂包埋-去包埋剂电镜制样方法,可清晰地显示核骨架-核纤层-中间纤维结构体系。成 分核骨架不象胞质骨架那样由非常专一的蛋白成分组成,核骨架的成分比较复杂,主要成分是核骨架蛋白及核骨架结合蛋白,并含有少量RNA。◆核骨架蛋白◆骨架结合蛋白◆其它核骨架结合序列◆ DNA序列中的核骨架结合序列(matrix\n\n【本页讲解】\n本页是一张待填写的三骨架对比表（微管 / 微丝 / 中间纤维），标准答案如下，建议对照记忆：①组成蛋白——微管 α、β-tubulin；微丝 actin；中间纤维为多种 IF 蛋白（角蛋白、vimentin、desmin、neurofilament 等）。②结合蛋白——微管 MAPs/tau；微丝有多种结合蛋白（原肌球蛋白、α-辅肌动蛋白等）；中间纤维相关蛋白（IFAPs），本身不结合核苷酸。③单体是否结合 GTP/ATP——β-tubulin 结合 GTP、actin 结合 ATP；中间纤维不结合核苷酸。④是否有极性——微管、微丝有极性；中间纤维无极性。⑤动态不稳定性——微管有明显动态不稳定性；微丝有踏车现象；中间纤维动态性低。⑥特异性药物——微管为秋水仙素/紫杉醇；微丝为细胞松弛素 B/鬼笔环肽；中间纤维无特异性药物。⑦马达蛋白——微管为驱动蛋白/动力蛋白；微丝为肌球蛋白；中间纤维无。⑧主要生理功能——微管：支架、胞内运输、纺锤体；微丝：细胞运动、收缩、皮层支撑；中间纤维：提供抗张强度、维持组织完整性。","page":26,"level":"掌握","img":"assets/img/ch08/p026.jpg","anim":null,"fig":null,"points":["从组成蛋白、结合蛋白、是否结合GTP/ATP、极性等方面比较微管、微丝、中间纤维","微管与微丝有极性、具动态不稳定性并有马达蛋白；中间纤维无极性、无马达蛋白","三者特异性药物及主要生理功能不同"],"check":{"q":"关于细胞骨架的马达蛋白与特异性药物，对应正确的是？","o":["A. 微管—肌球蛋白，药物为细胞松弛素B","B. 微丝—驱动蛋白，药物为秋水仙素","C. 微管—驱动蛋白/动力蛋白，药物为秋水仙素/紫杉醇","D. 中间纤维—动力蛋白，药物为鬼笔环肽"],"a":"C","e":"微管马达蛋白为驱动蛋白和动力蛋白，特异性药物为秋水仙素/紫杉醇；微丝马达为肌球蛋白，药物为细胞松弛素B/鬼笔环肽；中间纤维无马达蛋白和特异药物。","oe":["A. 错误，微管马达是驱动蛋白/动力蛋白，药物为秋水仙素。","B. 错误，微丝马达是肌球蛋白，药物为细胞松弛素B。","C. 正确，微管的马达蛋白及特异性药物对应正确。","D. 错误，中间纤维无马达蛋白，也无特异性药物。"]},"cards":null,"mem":"MF/MT/IF对比：极性、动态、药物、马达","big":"assets/img/ch08/big/p026.jpg"}],"mcq":[{"id":"ch08_mcq_2","mod":"3.5.4 表达有组织特异性，与细胞分化关系密切","modI":8,"q":"中等纤维中的结蛋白主要存在于（          ）。","o":["A．肌细胞","B．上皮细胞","C．神经细胞","D．间质细胞"],"a":"A","e":"中等纤维按其组织来源及免疫原性可分为 5 类，分别为角蛋白纤维，波形纤维，结 蛋白纤维，神经元纤维，神经胶质纤维。结蛋白纤维存在于肌细胞中。","kp":"ch08_s8_25","oe":["正确——结蛋白存在于肌细胞中，连接Z盘与细胞膜。","上皮细胞的中间纤维为角蛋白，非结蛋白。","神经细胞的中间纤维为神经丝蛋白，非结蛋白。","间质细胞主要表达波形蛋白，而非结蛋白。"]}],"judge":[{"id":"ch08_ajudge_9","modI":8,"q":"最初胚胎细胞中表达角蛋白      同时波形纤维蛋白表达","a":"对","e":"本页要点：最初胚胎细胞中表达角蛋白      同时波形纤维蛋白表达","kp":"ch08_s8_23","oe":["胚胎发育中常同时表达角蛋白与波形蛋白，该表述符合事实。","若判错，则早期胚胎细胞确可共表达角蛋白和波形蛋白。"]}],"fill":[],"short":[],"calc":[],"term":[]}],"mcq":[{"id":"ch08_mcq_1","mod":"3.3 中间纤维(IFs)的装配","modI":4,"q":"核纤层蛋白从氨基酸序列的同源比较上看，属于（            ）。","o":["A．微管","B．微丝","C．中间丝","D．核骨架蛋白"],"a":"C","e":"近年来发现核纤层与中间丝有许多共同点，通过对核纤层蛋白的 cDNA 克隆的研 究，并与中间丝的氨基酸序列对比，说明核纤层蛋白确实是中间丝蛋白家族成员。","kp":"ch08_s7_1","oe":["核纤层蛋白不属于微管蛋白，序列同源比较与之不符。","核纤层蛋白不属于微丝蛋白，也不是肌动蛋白。","正确——氨基酸序列同源比较表明核纤层蛋白属中间丝蛋白家族。","核骨架蛋白是功能分类，并非按序列同源比较的归属。"]},{"id":"ch08_mcq_2","mod":"3.5.4 表达有组织特异性，与细胞分化关系密切","modI":8,"q":"中等纤维中的结蛋白主要存在于（          ）。","o":["A．肌细胞","B．上皮细胞","C．神经细胞","D．间质细胞"],"a":"A","e":"中等纤维按其组织来源及免疫原性可分为 5 类，分别为角蛋白纤维，波形纤维，结 蛋白纤维，神经元纤维，神经胶质纤维。结蛋白纤维存在于肌细胞中。","kp":"ch08_s8_0","oe":["正确——结蛋白存在于肌细胞中，连接Z盘与细胞膜。","上皮细胞的中间纤维为角蛋白，非结蛋白。","神经细胞的中间纤维为神经丝蛋白，非结蛋白。","间质细胞主要表达波形蛋白，而非结蛋白。"]}],"judge":[{"id":"ch08_judge_1","modI":4,"q":"中间纤维蛋白合成后，基本上均组装为中间纤维，没有大量游离的单体存在。（                           ）","a":"对","e":"","kp":"ch08_s4_4","oe":["中间纤维蛋白合成后大多迅速组装成纤维，细胞内几乎无游离单体库。","若判错，则忽视中间纤维高度组装、无显著游离单体池的特点。"]},{"id":"ch08_ajudge_2","modI":0,"q":"直径10nm vs (微丝7nm, 微管 24nm)","a":"对","e":"本页要点：直径10nm vs (微丝7nm, 微管 24nm)","kp":"ch08_s3_0","oe":["胶质细胞中含胶质纤维酸性蛋白(GFAP)组成的胶质丝，表述正确。","若判错，则胶质细胞确含胶质丝，否定缺乏依据。"]},{"id":"ch08_ajudge_4","modI":1,"q":"角蛋白(keratin): 上皮细胞，如表皮细胞衍生的指甲、","a":"对","e":"本页要点：角蛋白(keratin): 上皮细胞，如表皮细胞衍生的指甲、","kp":"ch08_s1_2","oe":["中间纤维为细胞提供机械强度支持，是其重要功能，表述正确。","若判错，则与中间纤维提供机械支撑这一功能不符。"]},{"id":"ch08_ajudge_8","modI":5,"q":"在细胞内与中间纤维(IFs)共分布, 介导IFs之间以及中","a":"对","e":"本页要点：在细胞内与中间纤维(IFs)共分布, 介导IFs之间以及中","kp":"ch08_s5_0","oe":["桥粒斑蛋白等与中间纤维共分布，介导IFs间及其与膜结构的连接。","若判错，则这类连接蛋白确实介导中间纤维间的连接，否定无据。"]},{"id":"ch08_ajudge_9","modI":8,"q":"最初胚胎细胞中表达角蛋白      同时波形纤维蛋白表达","a":"对","e":"本页要点：最初胚胎细胞中表达角蛋白      同时波形纤维蛋白表达","kp":"ch08_s8_0","oe":["胚胎发育中常同时表达角蛋白与波形蛋白，该表述符合事实。","若判错，则早期胚胎细胞确可共表达角蛋白和波形蛋白。"]}],"fill":[{"id":"ch08_fill_1","modI":1,"q":"成熟肌细胞中的中间丝是______，上皮细胞的中间丝是______。","a":"结蛋白；角质蛋白","kp":"ch08_s1_0","oe":["成熟肌细胞中的中间丝，可将肌原纤维锚定于Z盘。","上皮细胞中的中间丝，构成细胞间机械支撑网络。"]},{"id":"ch08_fill_2","modI":4,"q":"中间丝的组装过程可以简要概括为______。","a":"形成双股螺旋的二聚体→组成反向半重叠的四聚体→形成原纤丝→形成中间纤维","kp":"ch08_s4_0","oe":["两条多肽形成双股螺旋二聚体，再反平行组成四聚体，进而形成原纤丝和纤维。"]},{"id":"ch08_fill_3","modI":5,"q":"与微管、微丝不同，中间纤维的装配不具有______。中间纤维的分布具有严格的______。","a":"极性；组织特异性。","kp":"ch08_s4_4","oe":["中间丝由反向平行四聚体组装，两端对称，故无极性。","不同类型中间丝蛋白分布不同组织，具严格组织特异性。"]},{"id":"ch08_fill_4","modI":1,"q":"中间纤维的分布具有严格的组织特异性，其中 主要存在于肌细胞中。[南开大学 2008 研]","a":"结蛋白","kp":"ch08_s8_0","oe":["结蛋白主要存在于肌细胞，是肌细胞中间纤维特征性蛋白。"]}],"term":[{"id":"ch08_term_1","modI":7,"term":"细胞骨架（cytoskeleton）。","def":"细胞骨架（cytoskeleton）是指细胞中的蛋白纤维网架体系，包括微丝、微管和中间丝。 细胞骨架是一种高度动态的结构体系。其主要功能有结构与支持作用；胞内运输作用；收缩 与运动；空间组织。","kps":"","kp":"ch08_s0_0"},{"id":"ch08_term_2","modI":7,"term":"cytoskeleton（Cytoskeleton）","def":"cytoskeleton 的中文名称是细胞骨架。细胞骨架是指用电子显微镜观察经非离子去污剂 处理后的细胞，可以在细胞质内观察到一个复杂的纤维状三维网络结构体系，包括微丝、微 管和中间纤维。细胞骨架为真核细胞所特有，它不仅是活细胞的支撑结构，决定细胞的形状 并赋予其强度，而且在细胞多种多样的生理活动（如细胞运动、膜泡运输和细胞分裂等）中 发挥着重要作用。","kps":"","kp":"ch08_s0_0"}],"short":[{"id":"ch08_short_1","modI":7,"q":"简述中间纤维的形态和分类。","a":"（1）中间纤维是一类蛋白质纤维系统，呈中空管状结构，其直径介于微管和微丝之间， 约为 19nm。 （2）中间纤维具有种属和组织特异性，根据其组织特异性的不同主要分为 5 类：①角质蛋 白纤维；②神经纤维蛋白；③结蛋白；④胶质纤维酸性蛋白；⑤波形纤维蛋白。","kp":"ch08_s1_0","kps":"中间纤维：直径约19nm介于微管微丝间；具特异性，分5类：角质蛋白、神经纤维蛋白、结蛋白、胶质纤维酸性蛋白、波形纤维蛋白"},{"id":"ch08_short_2","modI":5,"q":"为什么说中间丝具有异质性？","a":"中间丝具有多种类型，不同类型的中间丝蛋白其化学组成不同，主要表现在非α螺旋的 头部和尾部这两个结构域序列多变，长度相差甚远，在中间丝的组装过程中发挥重要的作用。","kp":"ch08_s3_0","kps":"类型多样、化学组成不同；非α螺旋头部和尾部结构域序列多变、长度相差大，在组装中作用重要"},{"id":"ch08_short_3","modI":4,"q":"微管和微丝这两种细胞骨架系统在细胞中都有一个巨大的蛋白库，但中间纤维系统却只 有很少的游离的组分，这是为什么？","a":"微管和微丝在细胞中都有一个巨大的蛋白库，但中间纤维系统却只有很少的游离的组分， 这主要与微管、微丝和中间纤维在组装和存在方式上的差异有关。 （1）微管和微丝都处于动态平衡状态，不停地组装和去组装，所以在细胞中含有一个巨大 的蛋白库。 （2）不同来源的组织细胞表达不同的中间纤维类型，通常在各自的细胞内形成同源多聚体， 中间纤维在合适的缓冲体系中能自我组装，而且组装过程中不需要 ATP 或 GTP 提供能量。 中间纤维的组装首先由两个单体的杆状区以平行排列的方式形成双股螺旋的二聚体，然后两 个二聚体以反向平行和半分子交错的形式组装成四聚体。四聚体是细胞质中中间纤维组装的 最小结构单位，对四聚体而言，没有极性。细胞内的新的中间纤维可以通过交换的方式插入 到原有的纤维中去，因此在细胞中不需要有大量的游离组分。","kp":"ch08_s4_4","kps":"①微管微丝动态平衡，故大蛋白库；②中间纤维同源多聚体、自我组装、不需ATP/GTP；二聚体→四聚体（最小单位）"},{"id":"ch08_short_y1","modI":0,"q":"比较中间纤维与微管、微丝在极性、亚基种类和组装方式上的差异。","a":"①极性：微管和微丝有极性，中间纤维无极性。②亚基种类：微管亚基为αβ-微管蛋白二聚体，微丝亚基为球状肌动蛋白G-actin，中间纤维亚基为多种纤维状蛋白（角蛋白、波形蛋白、结蛋白、神经丝蛋白、核纤层蛋白等），具组织特异性。③组装方式：微管、微丝由球状亚基聚合且依赖核苷酸（GTP/ATP），具动态性；中间纤维由纤维状蛋白分步组装为二聚体→四聚体→原纤丝→纤维，不依赖核苷酸，结构稳定、抗张力。","kps":"极性:有/有/无;亚基:αβ微管蛋白/G-actin/多种纤维蛋白;组装:依赖核苷酸动态/分步不依赖核苷酸稳定","type":"比较型","kp":"ch08_s3_0"}],"calc":[{"id":"ch08_calc_y2","modI":0,"q":"说明中间纤维的分步组装机制及其无极性、抗张力的结构基础。","a":"①分步组装：两条中间纤维蛋白单体以α螺旋区缠绕成二聚体；两个二聚体反向平行、半重叠排列成四聚体；四聚体首尾相连成原纤丝；多条原纤丝再组装成中间纤维。②无极性的原因：二聚体反向平行排列，使纤维两端结构对称，故无正负端之分。③抗张力的原因：反向平行与多级缠绕（α螺旋→二聚体→四聚体→原纤丝→纤维）使结构高度稳定、可拉伸而不易断裂，为细胞提供机械强度。④中间纤维无核苷酸结合、不依赖ATP/GTP，组装后可稳定存在。","kps":"二聚体→四聚体(反向平行)→原纤丝→纤维;反向平行→无极性;多级缠绕→抗张力;不依赖核苷酸","type":"机制型","kp":"ch08_s4_0"},{"id":"ch08_calc_y3","modI":0,"q":"设计实验鉴定某细胞中中间纤维的蛋白类型。","a":"思路：利用中间纤维蛋白的组织特异性和免疫学方法。①免疫荧光：分别用抗角蛋白、波形蛋白、结蛋白、神经丝蛋白等特异抗体染色，共聚焦观察该细胞中间纤维的阳性信号，并与细胞核/骨架标记共定位。②免疫印迹（Western blot）：提取细胞蛋白，用各型中间纤维抗体检测相应分子量条带。③对照：已知类型的细胞（如上皮细胞角蛋白、肌细胞结蛋白）。预期：出现阳性信号的抗体所对应的蛋白即为该细胞中间纤维的类型。","kps":"各型IF特异抗体;免疫荧光共定位;Western blot;对照(已知类型细胞);判定类型","type":"实验设计型","kp":"ch08_s1_0"}],"appcards":[{"front":"简述中间纤维的形态和分类。","back":"（1）中间纤维是一类蛋白质纤维系统，呈中空管状结构，其直径介于微管和微丝之间， 约为 19nm。 （2）中间纤维具有种属和组织特异性，根据其组织特异性的不同主要分为 5 类：①角质蛋 白纤维；②神经纤维蛋白；③结蛋白；④胶质纤维酸性蛋白；⑤波形纤维蛋白。","mod":7,"modName":"第三节 中间纤维 · 3.5.2 参与细胞连接 (桥粒、半桥粒)","points":""},{"front":"为什么说中间丝具有异质性？","back":"中间丝具有多种类型，不同类型的中间丝蛋白其化学组成不同，主要表现在非α螺旋的 头部和尾部这两个结构域序列多变，长度相差甚远，在中间丝的组装过程中发挥重要的作用。","mod":5,"modName":"第三节 中间纤维 · 3.4 中间纤维结合蛋白","points":""},{"front":"微管和微丝这两种细胞骨架系统在细胞中都有一个巨大的蛋白库，但中间纤维系统却只 有很少的游离的组分，这是为什么？","back":"微管和微丝在细胞中都有一个巨大的蛋白库，但中间纤维系统却只有很少的游离的组分， 这主要与微管、微丝和中间纤维在组装和存在方式上的差异有关。 （1）微管和微丝都处于动态平衡状态，不停地组装和去组装，所以在细胞中含有一个巨大 的蛋白库。 （2）不同来源的组织细胞表达不同的中间纤维类型，通常在各自的细胞内形成同源多聚体， 中间纤维在合适的缓冲体系中能自我组装，而且组装过程中不需要 ATP 或 GTP 提供能量。 中间纤维的组装首先由两个单体的杆状区以平行排列的方式形成双股螺旋的二聚体，然后两 个二聚体以反向平行和半分子交错的形式组装成四聚体。四聚体是细胞质中中间纤维组装的 最小结构单位，对四聚体而言，没有极性。细胞内的新的中间纤维可以通过交换的方式插入 到原有的纤维中去，因此在细胞中不需要有大量的游离组分。","mod":4,"modName":"第三节 中间纤维 · 3.3 中间纤维(IFs)的装配","points":""}],"jyq":[{"id":"jyq_ch08_1","kind":"mcq","q":"真核细胞的染色质主要是由以下成分构成的。A.DN","o":["A. RNA和组蛋白","B. DNA、组蛋白和非组蛋白","C. DNA、RNA和非组蛋白","D. RNA、组蛋白和非组蛋白"],"a":"B","src":"复旦大学，2001年","kp":null,"e":"染色质主要由DNA、组蛋白和少量非组蛋白组成，RNA含量极低。","oe":["A. RNA和组蛋白：错误，缺少DNA，DNA才是染色质的主要遗传成分。","B. DNA、组蛋白和非组蛋白：正确，三者为染色质的主要化学组成。","C. DNA、RNA和非组蛋白：错误，遗漏了含量最多的组蛋白。","D. RNA、组蛋白和非组蛋白：错误，缺少DNA，且染色质中RNA很少。"]},{"id":"jyq_ch08_2","kind":"judge","q":"经流式细胞仪分离出的细胞可继续培养。","a":"对","src":"上海交通大学，2007年","kp":null,"oe":["流式细胞仪分选时对细胞损伤较小，分选获得的目的细胞仍具活性，可继续培养，故“对”正确。","认为分选后细胞已受损死亡、不能培养的说法过于绝对，多数情况下细胞可存活，故“错”不成立。"]},{"id":"jyq_ch08_3","kind":"short","q":"原代细胞培养中，通常将动物组织进行或，进行最初的培养。","a":"切割组织；碎块贴壁；细胞离散（细胞悬液）。","src":"南京师范大学，2009年","kp":null},{"id":"jyq_ch08_4","kind":"short","q":"流式细胞仪可以定量测定细胞中的或某一种特异蛋白的含量，以及细胞群体中上述成分含量不同的细胞数量。","a":"DNA；RNA。第三章细胞生物学研究方法","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch08_5","kind":"judge","q":"核骨架的蛋白成分比较复杂，但这些蛋白成分都比较保守，并不随细胞类型及分化程度的不同而变化。","a":"错","src":"南京师范大学，2008年","kp":null,"oe":["核骨架蛋白成分复杂，其中确有部分较保守，但并非不随细胞类型变化。","核骨架蛋白随细胞类型和分化程度而变化，“并不变化”的说法过于绝对。"]},{"id":"jyq_ch08_6","kind":"judge","q":"与微丝不同，中间纤维蛋白合成后，基本上均组装为中间纤维，没有大量游离的单体存在。","a":"对","src":"南京师范大学，2008年","kp":null,"oe":["中间纤维蛋白合成后几乎全部聚合成纤维，胞内游离单体极少，与微丝不同。","若以为中间纤维像微丝那样有大量游离单体则错，其单体主要以纤维形式存在。"]},{"id":"jyq_ch08_7","kind":"judge","q":"近年来许多工作支持染色体骨架是染色体中的真实结构。","a":"对","src":"南京师范大学，2009年","kp":null,"oe":["多种实验证据支持染色体骨架真实存在，对维持染色体形态与功能有重要作用。","若认为染色体骨架只是制片假象则错，近年不少研究支持其为真实结构。"]},{"id":"jyq_ch08_8","kind":"mcq","q":"在细胞分级抽提方法中，为了溶去胞质微管和微丝，你认为该采用哪种抽提试剂（）。","o":["A. Triton","B. Tween40和脱氧胆酸钠","C. 核酸酶","D. 硫酸铵"],"a":"B","src":"南京师范大学，2009年","kp":null,"e":"细胞分级抽提中，非离子去垢剂Tween40与脱氧胆酸钠配合可溶去胞质微管和微丝。","oe":["A. Triton：错误，Triton X-100主要用于溶解细胞膜，对微管微丝作用有限。","B. Tween40和脱氧胆酸钠：正确，二者合用可溶解胞质微管和微丝。","C. 核酸酶：错误，核酸酶用于降解DNA或RNA，不能溶解细胞骨架。","D. 硫酸铵：错误，硫酸铵用于盐析沉淀蛋白质，不溶解微管微丝。"]},{"id":"jyq_ch08_9","kind":"mcq","q":"具ATP酶活性的蛋白有（）。","o":["A. 动力蛋白，微管蛋白，肌动蛋白","B. 肌钙蛋白，肌球蛋白，微管蛋白","C. 肌球蛋白，动力蛋白，驱动蛋白","D. 血影蛋白，原肌球蛋白，动力蛋白"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"肌球蛋白、动力蛋白和驱动蛋白均为马达蛋白，都具有ATP酶活性。","oe":["A. 动力蛋白，微管蛋白，肌动蛋白：错误，微管蛋白和肌动蛋白本身无ATP酶活性。","B. 肌钙蛋白，肌球蛋白，微管蛋白：错误，肌钙蛋白和微管蛋白无ATP酶活性。","C. 肌球蛋白，动力蛋白，驱动蛋白：正确，三者均为具ATP酶活性的马达蛋白。","D. 血影蛋白，原肌球蛋白，动力蛋白：错误，血影蛋白和原肌球蛋白无ATP酶活性。"]},{"id":"jyq_ch08_10","kind":"short","q":"核体（nuclearbodies）","a":"间期核内除染色质与核仁结构外，在染色质之间的空间还含许多形态上不同的亚核结构域（subnucleardomain），统称为核体。如螺旋体和早幼粒细胞白血病蛋白体。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch08_11","kind":"short","q":"秋水仙素可抑制着丝粒的分裂而促使细胞染色体加倍，细胞松弛素B处理动物细胞可促使细胞融合而形成多核细胞。","a":"错。改：秋水仙素可抑制纺锤体的形成而促使细胞染色体加倍，细胞松弛素B处理动物细胞微丝网络结构破坏，缢束消失使细胞成圆球状多核细胞。","src":"华中师范大学，2007年","kp":null},{"id":"jyq_ch08_12","kind":"fill","q":"染色体骨架的主要成分是组蛋白。","a":"对。第十一章细胞核与染色体","src":"华中师范大学，2007年","kp":null,"oe":["染色体骨架(支架)主要由非组蛋白构成，组蛋白是核小体的组成成分，该说法应为错误（原答案标注对，疑有误）。"],"doubt":1},{"id":"jyq_ch08_13","kind":"judge","q":"细胞分裂期间，核膜发生解体和重建的周期性变化是与核纤层发生的去组装和重新组装密切相关的。","a":"对","src":"南京师范大学，2009年","kp":null,"oe":["核纤层蛋白去组装致核膜解体，重新组装则核膜重建，二者周期变化密切相关。","若把核膜解体、重建与核纤层组装割裂开则错，二者变化是密切相关的。"]},{"id":"jyq_ch08_14","kind":"short","q":"核膜上孔膜的特征性蛋白为一种跨膜糖蛋白核纤层通过与核膜相连。","a":"gp210；核纤层蛋白B。","src":"山东大学，2006年","kp":null},{"id":"jyq_ch08_15","kind":"fill","q":"根据等电点的不同，可将核纤层蛋白分为和两类。","a":"近中性；偏酸性。","src":"南京师范大学，2008年","kp":null,"oe":["按等电点分，核纤层蛋白中有近中性的一类，如A型核纤层蛋白。","另一类偏酸性，如B型核纤层蛋白，与核膜结合较牢固。"]},{"id":"jyq_ch08_16","kind":"mcq","q":"核仁的大小随细胞代谢状态而变化，下列4种细胞中，核仁最大的是（）。","o":["A. 肌细胞","B. 肝细胞","C. 浆细胞","D. 上皮细胞"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"核仁大小与蛋白质合成活跃程度相关，浆细胞大量合成抗体，核仁最大。","oe":["A. 肌细胞：错误，肌细胞蛋白质合成不如浆细胞旺盛，核仁较小。","B. 肝细胞：错误，肝细胞有一定蛋白合成，但仍不及浆细胞活跃。","C. 浆细胞：正确，浆细胞大量合成免疫球蛋白，核仁明显增大。","D. 上皮细胞：错误，其蛋白质合成活性一般，核仁较小。"]},{"id":"jyq_ch08_17","kind":"mcq","q":"有丝分裂前期末核膜的崩解和末期核膜的重组，与以下蛋白的磷酸化以及去磷酸化有关（","o":["A. 染色体蛋白","B. H,组蛋白","C. 核纤层蛋白","D. 核仁蛋白"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"核纤层蛋白的磷酸化使核纤层解聚、核膜崩解，去磷酸化则参与核膜重组。","oe":["A. 染色体蛋白：错误，染色体蛋白与核膜的崩解和重组无直接关系。","B. H1组蛋白：错误，H1磷酸化主要与染色质凝缩有关，非核膜变化主因。","C. 核纤层蛋白：正确，其磷酸化与去磷酸化直接控制核纤层和核膜的解聚与重组。","D. 核仁蛋白：错误，核仁蛋白与核仁解体有关，不主导核膜变化。"]},{"id":"jyq_ch08_18","kind":"mcq","q":"染色体支架蛋白是（）。","o":["A. 微管蛋白","B. 核纤层蛋白","C. 非组蛋白","D. 组蛋白"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"染色体支架由非组蛋白构成，是维持染色体形态的骨架结构。","oe":["A. 微管蛋白：错误，微管蛋白构成纺锤体微管，不是染色体支架。","B. 核纤层蛋白：错误，核纤层蛋白位于核膜内侧，不是染色体支架成分。","C. 非组蛋白：正确，染色体支架蛋白属于非组蛋白。","D. 组蛋白：错误，组蛋白与DNA结合形成核小体，不是支架成分。"]},{"id":"jyq_ch08_19","kind":"short","q":"简述核骨架的功能。","a":"核骨架的功能有：①核骨架为DNA的复制提供一个支架；②为基因的表达提供结合位点；③为病毒复制时的DNA复制、RNA转录及装配提供支架；4核骨架与染色体的构建密切相关。","src":"华中师范大学，2008年","kp":null},{"id":"jyq_ch08_20","kind":"short","q":"简述核膜在细胞周期中的动态变化和调控机制。","a":"在真核细胞的细胞周期中，核被膜在有规律的解体与重建，在分裂期，双层核膜崩解成单层膜泡，核孔复合体解体，核纤层去组装，到分裂末期，核膜开始围绕染色体重新形成，其中旧核膜参与了新核膜的构建。目前越来越多的证据表明，一种直径200nm左右的单层小膜泡直接参与了核膜的形成，它们首先附着到染色质的表面，在染色质表面排列并相互融合形成双层膜，同时在膜上的某些部位内、外膜相互融合并形成核孔复合体结构。在有丝分裂后期核被膜重建时，富含LBR的膜泡首先与染色质结合，而富含gp210的膜泡与染色质结合较晚，说明核被膜的去组装不是随机的。近期研究还发现，RanGTP酶及其结合蛋白参与了核被膜的组装调控。此外，核被膜的去组装、重组装变化受细胞周期调控因子的调节，这种调节作用可能通过核纤层蛋白、核孔复合体蛋白等进行磷酸化与去磷酸化修饰来实现。","src":"中国科学院，2007年","kp":null},{"id":"jyq_ch08_21","kind":"short","q":"试述从DNA到染色体的包装过程。DNA为什么要包装成染色质？","a":"答染色质包装的多级螺旋模型：一级结构：核小体二级结构：螺线管（solenoid）三级结构：超螺线管（supersolenoid）四级结构：染色单体（chromatid）压缩7倍压缩6倍压缩40倍压缩5倍DNA-→核小体一→螺线管→超螺线管→染色单体即：DNA双股螺旋分子缠绕组蛋白八聚体，形成核小体（一级结构），核小体紧密连接成直径为11nm的串珠链，6个核小体为一圈螺旋缠绕成外径30nm。内径10nm的螺线管（二级结构），螺线管再行盘绕成直径为300nm的超螺线管（三级结构），超螺线管再经折叠形成染色单体（四级结构）。DNA包装成染色体后，长度压缩了近万倍，更易在细胞核狭小的空间内存在，利于顺利完成复制、转录和分离。染色质结构的形成使得真核生物基因结构更加复杂，调节机制更加多样，从而使真核生物更能适应环境。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch08_22","kind":"fill","q":"核糖体中各组成成分是以键结合在一起的，其组装方式称为。","a":"非共价；自我装配。","src":"南京师范大学，2008年","kp":null,"oe":["核糖体各组成成分之间主要以非共价键结合，易于组装与解离。","其组装无需模板和酶，靠各成分间的相互作用自我装配而成。"]},{"id":"jyq_ch08_23","kind":"judge","q":"有丝分裂前期，核纤层蛋白去磷酸化使核膜破裂。","a":"错","src":"上海交通大学，2007年","kp":null,"oe":["核纤层蛋白的磷酸化确与核膜解体有关，但题中把过程写成去磷酸化，故有误。","前期是核纤层蛋白磷酸化（CDK1催化）使核纤层解聚、核膜破裂，故原说法错误。"]},{"id":"jyq_ch08_24","kind":"short","q":"细胞周期可以通过某些方式同步化，最重要的是人工细胞周期同步方法包括和","a":"人工选择；人工诱导。","src":"湖北大学，2008年","kp":null},{"id":"jyq_ch08_25","kind":"fill","q":"几乎所有细胞的染色质在有丝分裂期间都是可见的，它们通过螺旋化形成高度聚缩的结构，称为；它们在有丝分裂中期的特征，被称为。","a":"染色体；核型。","src":"南京师范大学，2008年","kp":null,"oe":["染色质高度螺旋聚缩形成的结构称为染色体，是遗传物质的载体。","有丝分裂中期染色体的大小、形态和数目特征称为核型(染色体组型)。"]},{"id":"jyq_ch08_26","kind":"short","q":"细胞周期同步化方法大致可分三类","a":"DNA合成阻断法；分裂中期阻断法；利用条件依赖性突变株法。第十三章细胞周期与细胞分裂【答案】通过某些药物，如秋水仙素等，抑制微管聚合，从而有效抑制细胞分裂器的形成，将细胞阻断在细胞分裂中期。","src":"山东大学，2006年","kp":null},{"id":"jyq_ch08_27","kind":"mcq","q":"以下可以作为细胞周期同步化的方法有（）。","o":["A.条件依赖突变株和DNA脉冲标记法","B.DNA合成阻断法和分裂中期阻断法","C.DNA合成阻断法和DNA脉冲标记法"],"a":"B","src":"湖北大学，2007年","kp":null,"e":"细胞周期同步化常用DNA合成阻断法和分裂中期阻断法。","oe":["A. 条件依赖突变株和DNA脉冲标记法：错误，脉冲标记用于追踪细胞，不能同步化。","B. DNA合成阻断法和分裂中期阻断法：正确，二者可将细胞阻断于特定时相而同步。","C. DNA合成阻断法和DNA脉冲标记法：错误，脉冲标记法不是同步化方法。"]},{"id":"jyq_ch08_28","kind":"mcq","q":"用“有丝分裂选择法”制备M期同步细胞时，宜采用（）。","o":["A. 生长致密的单层培养细胞","B. 生长旺盛的悬浮培养细胞","C. 单层培养，处于对数生长期的细胞","D. 分裂相多的骨髓细胞"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"有丝分裂选择法利用M期细胞贴壁不牢的特点，宜用对数生长期单层培养细胞。","oe":["A. 生长致密的单层培养细胞：错误，过于致密，分裂细胞少，不利选择。","B. 生长旺盛的悬浮培养细胞：错误，悬浮细胞不贴壁，无法用抖落法选择。","C. 单层培养，处于对数生长期的细胞：正确，分裂活跃且贴壁不牢，便于选择。","D. 分裂相多的骨髓细胞：错误，骨髓细胞不适用有丝分裂选择法。"]},{"id":"jyq_ch08_29","kind":"short","q":"细胞周期时间是如何测定的？","a":"细胞周期长短测定可以采用：①脉冲标记DNA复制和细胞分裂指数观察测定法；②流式细胞仪测定法；③缩时摄像技术，可以得到准确的细胞周期时间及分裂间期和分裂期的准确时间。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch08_30","kind":"short","q":"细胞周期同步化有哪些方法？","a":"比较其优缺点？容细胞同步化是指自然的，或经人为选择或诱导产生的细胞周期同步化。前者称为自然同步化，后者称为人工同步化。自然同步化是自然界存在的现象，在动、植物细胞都有发现。它们不受人为条件的干扰，因而有可能在接近自然的条件下进行观察。由于自然同步化的细胞群体受到诸多条件的限制，因而促进了细胞培养的各种人工同步化方法的发展。所以，人工同步化比较普遍使用的是体外培养细胞，大致可分为选择同步化、诱导同步化或者两者的结合。（1)选择同步化：主要是有丝分裂选择法。经单层培养可获得一定数量的M期细胞。单层培养于培养器血中的细胞使之处于对数期增殖，此时细胞分裂活跃，分裂指数高，分裂镰物释询培养器的70黏着性降低。此法的优点是不受药物影响，同步化程度高。缺点是分离的细胞少。另一个方法是密度梯度离心法：根据不同时期的细胞在体积和重量上存在的差别进行分离。此法的优点是简单省时，效率高，成本低。缺点是对大多数种类的细胞并不适用。(2)诱导同步化：转，最终将细胞群体阻断在S期。TdR双阻断法最常用，细胞最终阻断于G/S交界处。优点是同步化效率高，几乎适合与所有体外培养的细胞体系。缺点是诱导过程可造成细胞非均衡生长。②中期阻断法：利用秋水仙素等抑制有丝分裂器的形成，将细胞阻断在有丝分裂中期。此法的优点操作简便，效率高。缺点是这些药物的毒性相对较大。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch08_31","kind":"short","q":"化学致癌（chemicalcarcinogenesis）","a":"很多癌是由环境因子引起，其由化学物质（包括自然存在的和人工合成的）而引起的癌症发生称为化学致癌。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch08_32","kind":"fill","q":"细胞周期中的引擎是和。","a":"周期蛋白（cyclin）；周期蛋白依赖激酶（CDKs）。","src":"南京师范大学，2008年","kp":null,"oe":["周期蛋白(cyclin)是细胞周期引擎的调节亚基，含量随周期呈周期性变化。","周期蛋白依赖激酶(CDKs)是催化亚基，需与周期蛋白结合才具活性。"]},{"id":"jyq_ch08_33","kind":"fill","q":"细胞周期中的两个关键时期相互转化的点是和，其中是催化亚基，相当于调节亚基。","a":"CDK；周期蛋白；CDK；周期蛋白。","src":"北京大学，1996年","kp":null,"oe":["细胞周期转化的分子开关是CDK，即周期蛋白依赖激酶。","周期蛋白是调节亚基，其周期性合成与降解控制CDK的激活。","CDK作为催化亚基具激酶活性，可磷酸化底物驱动周期进程。","周期蛋白相当于调节亚基，决定CDK的底物特异性和激活时机。"]},{"id":"jyq_ch08_34","kind":"mcq","q":"破坏框主要存在于（）周期蛋白分子中。","o":["A. G期","B. S期","C. G2期","D. M期"],"a":"D","src":"湖北大学，2008年","kp":null,"e":"破坏框是M期周期蛋白N端的特异序列，介导其被泛素化后快速降解。","oe":["A. G1期：错误，G1期周期蛋白不含破坏框。","B. S期：错误，S期周期蛋白不含破坏框。","C. G2期：错误，破坏框主要见于M期周期蛋白。","D. M期：正确，M期周期蛋白含破坏框，降解后使MPF失活。"]},{"id":"jyq_ch08_35","kind":"mcq","q":"核癌蛋白是与何种物质结合，促进DNA复制和细胞有丝分裂（）。","o":["A. mRNA","B. 组蛋白","C. DNA","D. 非组蛋白"],"a":"C","src":"南京师范大学，2009年","kp":null,"e":"核癌蛋白与DNA结合，促进DNA复制和细胞有丝分裂。","oe":["A. mRNA：错误，核癌蛋白作用于DNA而非mRNA。","B. 组蛋白：错误，核癌蛋白并不通过结合组蛋白发挥作用。","C. DNA：正确，核癌蛋白与DNA结合，启动复制并促进分裂。","D. 非组蛋白：错误，其结合靶标是DNA而非非组蛋白。"]},{"id":"jyq_ch08_36","kind":"short","q":"CDK的中文名称是什么？举例说明CDK在细胞周期中的作用。","a":"CDK是周期蛋白依赖性蛋白激酶（cyclindependentkinase），是细胞周期调控中的重要因素，是细胞周期运行的引擎分子。目前在哺乳动物细胞内至少存在12种CDK激酶。一般情况下，CDK激酶至少有两个亚单位，即周期蛋白和CDK蛋白，周期蛋白为调节亚单位，CDK蛋白为其催化亚单位。CDK激酶通过磷酸化其底物对细胞周期进行调控。CDK激酶活性也受其他因素的直接调节。不同的CDK激酶与不同的周期蛋白结合，执行不同的调节功能。如与G期周期蛋白激酶结合的CDK激酶在G期起调节作用，与M期周期蛋白结合的CDK激酶在M期起调节作用。CDK激酶是蛋白质激酶家族中的一员，依赖与周期蛋白的结合来执行细胞周期有规律地进行中的关键功能。不同的CDK-周期蛋白复合物使特异的靶蛋白磷酸化而激发细胞周期的进行。当缺乏它们的周期蛋白质搭档，或有CDK抑制物存在时，它们即失去活性。","src":"华东师大，2009年","kp":null},{"id":"jyq_ch08_37","kind":"short","q":"举例说明CDK在细胞周期中是如何执行调节功能的。","a":"答细胞周期调控包括正调控、负调控和信号反应。CDK是正调控因子，它是细胞沿周期运行的引擎蛋白。以MPF为例阐述CDK在细胞周期中的调节功能。MPF是一种使多种底物蛋白磷酸化的蛋白激酶，由M期cyclin-CDK一细胞周期依赖性蛋白激酶形成的复合物。该复合物MPF=CDKl=p34c+周期蛋白B（p34+cyclinB)。CDKl活性首先依赖于周期蛋白B含量的积累。周期蛋白B一般在G期的晚期开始合成，通过S期，其含量不断增加，到达G2期，其含量达到最大值，MPF的活性随cyclinB浓度变化而变化。MPF的活化还受到激酶与磷酸酶的调节。活化的MPF可使更多的MPF活化。随周期蛋自B含量达到一定程度，CDKI活性开始出现。到G期晚期阶段，CDKI（MPF)活性达到最大值并一直维持到M期的中期阶段。活化的MPF促使分裂期细胞在分裂前期执行下列生化事件：①染色质开始浓缩形成有丝分裂染色体；②细胞骨架解聚，有丝分裂纺锤体开始装配；③高尔基复合体、内质网等细胞器解体，形成小的膜泡。在有丝分裂的后期，活化的后期促进因子APC主要介导两类蛋白质降解：后期抑制因子和有丝分裂周期蛋白。前者维持姐妹染色单体粘连，抑制后期启动；后者的降解意味着MPF失去活性，有丝分裂即将结束，即染色体开始去凝集，核膜重建。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch08_38","kind":"fill","q":"中间纤维家族的成分在表达时呈组织特异性，其中在于上皮细胞的是，而波形纤维存在于来源的细胞。","a":"角蛋白纤维；间质细胞和中胚层。","src":"南开大学，2009年","kp":null,"oe":["上皮细胞中的中间纤维是角蛋白纤维，由角蛋白构成，具组织特异性。","波形纤维(vimentin)主要存在于间质细胞和中胚层来源的细胞中。"]},{"id":"jyq_ch08_39","kind":"mcq","q":"下列哪类细胞具有分化能力（）。","o":["A. 肝细胞","B. 肾细胞","C. 胚胎细胞","D. 神经细胞"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"胚胎细胞分化程度低，具有全能性或多能性，可分化为多种细胞。","oe":["A. 肝细胞：错误，肝细胞已分化，分化能力有限。","B. 肾细胞：错误，肾细胞已高度分化。","C. 胚胎细胞：正确，胚胎细胞未分化或低分化，具发育全能性。","D. 神经细胞：错误，神经细胞为终末分化细胞，一般不再分化。"]},{"id":"jyq_ch08_40","kind":"mcq","q":"摇蚊受精卵的前端受紫外线照射后，将发育为（","o":["A. 无头胚胎","B. 双腹胚胎","C. 无胸胚胎","D. 双胸胚胎"],"a":"B","src":"姜益泉《辅导与习题集》","kp":null,"e":"前端紫外照射破坏前端决定子，胚胎前端结构缺失、后端重复，发育为双腹胚胎。","oe":["A. 无头胚胎：错误，前端因子破坏主要表现为后端结构重复。","B. 双腹胚胎：正确，前端决定子被破坏后尾端结构重复形成。","C. 无胸胚胎：错误，无胸是后端决定子缺失的表现。","D. 双胸胚胎：错误，双胸由后端因子异常引起，与前端照射相反。"]},{"id":"jyq_ch08_41","kind":"short","q":"细胞骨架成分参与多种细胞结构的组成，微丝参与的细胞连接方式指。","a":"黏着带和黏着斑。","src":"南开大学，2009年","kp":null},{"id":"jyq_ch08_42","kind":"fill","q":"细胞外被主要含有和两种成分。","a":"膜脂；膜蛋白。","src":"湖北大学，2007年","kp":null,"oe":["细胞膜的基本骨架是膜脂，主要以磷脂双分子层形式存在。","膜蛋白镶嵌或贯穿于脂双层中，执行运输、受体等功能。（注：若严格指糖萼，则主要成分为糖蛋白和糖脂）"]}],"outline":["中间纤维类型","逐级组装(无极性)","组织特异性表达","与细胞分化","功能(抗张/桥粒)"],"outlineMap":[0,2,8,8,8]};